def _safe_json_loads(value: str) -> Any:
    try:
        return json.loads(value)
    except Exception:  # noqa: BLE001
        return None


def _safe_social_profile_json_loads(value: str) -> Any:
    parsed = _safe_json_loads(value)
    if parsed is not None:
        return parsed
    text = str(value or "").strip()
    if not text.startswith("FORGE-ENC-v"):
        return None
    try:
        from forge.opsec.crypto import decrypt_string

        decrypted = decrypt_string(text)
    except Exception:  # noqa: BLE001
        return None
    return _safe_json_loads(decrypted)


def _normalize_root_domain(host: str) -> str:
    labels = [part for part in host.lower().strip(".").split(".") if part]
    if len(labels) >= 3 and len(labels[-1]) == 2 and labels[-2] in _COMMON_SECOND_LEVEL_PUBLIC_SUFFIXES:
        return ".".join(labels[-3:])
    if len(labels) >= 2:
        return ".".join(labels[-2:])
    return host.lower().strip(".")


def _is_placeholder_host_ip(value: str) -> bool:
    text = str(value or "").strip()
    if not text or text in {"0.0.0.0", "::", "::0"}:
        return True
    try:
        parsed_ip = ipaddress.ip_address(text)
    except ValueError:
        return False
    if parsed_ip.is_unspecified:
        return True
    if parsed_ip.version == 4 and parsed_ip in ipaddress.ip_network("198.18.0.0/15"):
        return True
    return False


_MOBILE_BUNDLE_SEED_SUFFIXES = (".apk", ".ipa", ".aab", ".apkm", ".apks", ".xapk")


def _is_mobile_bundle_url(value: str) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    parsed = urlparse(text)
    return (
        parsed.scheme in {"http", "https"}
        and bool(parsed.netloc)
        and parsed.path.lower().endswith(_MOBILE_BUNDLE_SEED_SUFFIXES)
    )


def _is_mobile_bundle_path(value: str | Path) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    return Path(text).suffix.lower() in _MOBILE_BUNDLE_SEED_SUFFIXES


# ---------------------------------------------------------------------------
# Cloud provider hostname detection (used by the seed classifier)
# ---------------------------------------------------------------------------
#
# A hostname whose suffix matches any of these is a cloud provider
# reference and gets classified as ``cloud_ref`` instead of ``url`` /
# ``domain``. Ordered by specificity; longer suffixes come first so
# ``.s3.amazonaws.com`` doesn't fall through to a broader match.
_CLOUD_REF_HOSTNAME_SUFFIXES: tuple[str, ...] = (
    # Supabase
    ".supabase.co",
    ".supabase.in",
    # Firebase / Google
    ".firebaseio.com",
    ".firebaseapp.com",
    ".web.app",
    ".appspot.com",
    ".storage.googleapis.com",
    # Amazon S3 + CloudFront + Amplify
    ".s3.amazonaws.com",
    ".s3-website.amazonaws.com",
    ".amplifyapp.com",
    ".cloudfront.net",
    # Azure Storage
    ".blob.core.windows.net",
    ".dfs.core.windows.net",
    ".file.core.windows.net",
    ".queue.core.windows.net",
    ".table.core.windows.net",
    # DigitalOcean Spaces
    ".digitaloceanspaces.com",
    # Vercel / Netlify (serverless hosting refs)
    ".vercel.app",
    ".netlify.app",
    ".netlify.com",
    # Cloudflare Pages / Workers
    ".pages.dev",
    ".workers.dev",
)

# Regional S3/GCS/Firebase RTDB hostnames not covered by simple suffix
# e.g. ``mybucket.s3.us-east-1.amazonaws.com`` or ``s3-us-west-2.amazonaws.com``.
_CLOUD_REF_HOSTNAME_REGEXES: tuple[re.Pattern[str], ...] = (
    re.compile(r"^[a-z0-9][a-z0-9.\-]*\.s3[.-][a-z0-9\-]+\.amazonaws\.com$"),
    re.compile(r"^s3[.-][a-z0-9\-]+\.amazonaws\.com$"),
    re.compile(r"^[a-z0-9][a-z0-9.\-]*\.storage\.googleapis\.com$"),
    re.compile(r"^[a-z0-9][a-z0-9\-]*(?:\.[a-z0-9][a-z0-9\-]*)*\.firebasedatabase\.app$"),
    re.compile(r"^storage\.cloud\.google\.com$"),
)

_CLOUD_REF_LITERAL_SERVICE_ALIASES: dict[str, str] = {
    "amplify": "amplify",
    "appspot": "gcp_appspot",
    "aws_s3": "aws_s3",
    "azure": "azure_blob",
    "azure_blob": "azure_blob",
    "azblob": "azure_blob",
    "cf_pages": "cloudflare_pages",
    "cf_r2": "cloudflare_r2",
    "cf_workers": "cloudflare_worker",
    "cloudflare_pages": "cloudflare_pages",
    "cloudflare_r2": "cloudflare_r2",
    "cloudflare_worker": "cloudflare_worker",
    "do_spaces": "do_spaces",
    "digitalocean_spaces": "do_spaces",
    "firebase": "firebase",
    "gcp_appspot": "gcp_appspot",
    "gcp_cloudfunctions": "gcp_cloudfunctions",
    "gcs": "gcs",
    "github_pages": "github_pages",
    "gitlab_pages": "gitlab_pages",
    "google_cloud_storage": "gcs",
    "gs": "gcs",
    "netlify": "netlify",
    "r2": "cloudflare_r2",
    "s3": "aws_s3",
    "supabase": "supabase",
    "vercel": "vercel",
}


def _normalize_cloud_ref_literal_service(value: str) -> str:
    token = re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")
    return _CLOUD_REF_LITERAL_SERVICE_ALIASES.get(token, "")


def _normalize_cloud_ref_literal_identifier(value: str) -> str:
    identifier = str(value or "").strip().strip("'\"").strip()
    if not identifier or any(char.isspace() for char in identifier):
        return ""
    return identifier.strip("/").lower()


def _parse_literal_cloud_ref(value: str) -> tuple[str, str] | None:
    """Parse operator-entered cloud refs such as ``aws_s3:bucket`` or ``s3://bucket``."""
    text = str(value or "").strip()
    if not text:
        return None
    lowered = text.lower()
    if lowered.startswith("arn:aws:s3:::"):
        bucket = text.split(":::", 1)[1].split("/", 1)[0]
        identifier = _normalize_cloud_ref_literal_identifier(bucket)
        return ("aws_s3", identifier) if identifier else None
    if lowered.startswith("aws:s3:"):
        identifier = _normalize_cloud_ref_literal_identifier(text.split(":", 2)[2].lstrip(":"))
        return ("aws_s3", identifier) if identifier else None
    if lowered.startswith("cloud_ref:"):
        body = text.split(":", 1)[1].strip()
        nested = _parse_literal_cloud_ref(body)
        if nested is not None:
            return nested
        if ":" not in body:
            return None
        service, identifier_text = body.split(":", 1)
        service_name = _normalize_cloud_ref_literal_service(service)
        identifier = _normalize_cloud_ref_literal_identifier(identifier_text)
        return (service_name, identifier) if service_name and identifier else None

    parsed = urlparse(text)
    service_name = _normalize_cloud_ref_literal_service(parsed.scheme)
    if service_name:
        if parsed.netloc:
            path = str(parsed.path or "").strip("/")
            if service_name in {"aws_s3", "gcs"}:
                identifier_text = parsed.netloc
            elif path:
                identifier_text = f"{parsed.netloc}/{path}"
            else:
                identifier_text = parsed.netloc
        else:
            identifier_text = parsed.path
        identifier = _normalize_cloud_ref_literal_identifier(identifier_text)
        return (service_name, identifier) if identifier else None

    if ":" in text:
        service, identifier_text = text.split(":", 1)
        service_name = _normalize_cloud_ref_literal_service(service)
        identifier = _normalize_cloud_ref_literal_identifier(identifier_text)
        return (service_name, identifier) if service_name and identifier else None
    return None


def _canonical_cloud_ref_value(value: str) -> str | None:
    parsed = _parse_literal_cloud_ref(value)
    if parsed is None:
        return None
    service, identifier = parsed
    return f"{service}:{identifier}"


def _hostname_is_cloud_ref(hostname: str) -> bool:
    """Return True when *hostname* looks like a cloud provider reference.

    Comparison is case-insensitive; leading wildcards and dots are
    stripped so ``*.myapp.supabase.co`` and ``myapp.supabase.co`` both
    match.
    """
    host = hostname.strip().lower()
    if "@" in host:
        host = host.rsplit("@", 1)[-1]
    if host.startswith("[") and "]" in host:
        host = host[1:host.index("]")]
    elif host.count(":") == 1:
        host = host.rsplit(":", 1)[0]
    host = host.lstrip("*").lstrip(".")
    if not host:
        return False
    for suffix in _CLOUD_REF_HOSTNAME_SUFFIXES:
        # `.suffix` match plus the bare-suffix hostname (e.g. "workers.dev" itself)
        if host.endswith(suffix) or host == suffix.lstrip("."):
            return True
    for pattern in _CLOUD_REF_HOSTNAME_REGEXES:
        if pattern.match(host):
            return True
    return False


def _classify_seed_value(value: str) -> str:
    text = value.strip()
    if not text:
        return "other"
    lowered = text.lower()
    if re.match(r"^\+\d{6,15}$", text):
        return "phone"
    if re.match(r"^@[a-z0-9_.\-]{2,32}$", lowered):
        return "username"
    try:
        parsed_ip = ipaddress.ip_address(text)
        return "ipv6" if parsed_ip.version == 6 else "ipv4"
    except ValueError:
        pass
    if _canonical_cloud_ref_value(text):
        return "cloud_ref"
    parsed = urlparse(text)
    if parsed.scheme in {"http", "https"} and parsed.netloc:
        if _is_mobile_bundle_url(text):
            return "apk_url"
        # Check cloud_ref BEFORE returning generic url — cloud references get
        # their own class so reporting, graph, and scope routing can single
        # them out from long-tail HTTP crawl URLs.
        if _hostname_is_cloud_ref(parsed.netloc):
            return "cloud_ref"
        return "url"
    if re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", text):
        return "email"
    if lowered.startswith("*."):
        lowered = lowered[2:]
    # Bare cloud provider hostname (no scheme) is still a cloud_ref, not a
    # generic domain — e.g. ``xyz.supabase.co`` or ``app.firebaseio.com``.
    if _hostname_is_cloud_ref(lowered):
        return "cloud_ref"
    if re.match(
        r"^[a-z0-9]([a-z0-9\-]*[a-z0-9])?(?:\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)+$",
        lowered,
    ):
        return "domain"
    if _looks_like_company_name(text):
        return "company"
    if _looks_like_person_name(text):
        return "name"
    return "other"


def _looks_like_person_name(value: str) -> bool:
    tokens = [token for token in re.split(r"\s+", value.strip()) if token]
    if len(tokens) < 2 or len(tokens) > 4:
        return False
    if any(token.lower().strip(".,") in _COMPANY_SUFFIXES for token in tokens):
        return False
    return all(re.match(r"^[A-Za-z][A-Za-z'\-]*$", token) for token in tokens)


def _looks_like_company_name(value: str) -> bool:
    tokens = [token.strip(".,") for token in re.split(r"\s+", value.strip()) if token]
    if len(tokens) < 2:
        return False
    return any(token.lower() in _COMPANY_SUFFIXES for token in tokens)


def _is_social_platform_host(hostname: str) -> bool:
    host = hostname.strip().lower().lstrip(".")
    if host.startswith("www."):
        host = host[4:]
    return (
        any(host == domain or host.endswith(f".{domain}") for domain in _SOCIAL_PLATFORM_DOMAINS)
        or _is_stack_exchange_network_host(host)
        or _is_mastodon_instance_host(host)
    )


def _is_stack_exchange_network_host(hostname: str) -> bool:
    host = hostname.strip().lower().lstrip(".")
    if host.startswith("www."):
        host = host[4:]
    return host in {"askubuntu.com", "mathoverflow.net", "serverfault.com", "stackapps.com", "superuser.com"}


def _is_mastodon_instance_host(hostname: str) -> bool:
    host = hostname.strip().lower().lstrip(".")
    if host.startswith("www."):
        host = host[4:]
    if any(host == domain or host.endswith(f".{domain}") for domain in _MASTODON_INSTANCE_DOMAINS):
        return True
    return host.startswith("mastodon.") or host.startswith("mstdn.")


def _is_managed_cloud_provider_host(hostname: str) -> bool:
    host = hostname.strip().lower().lstrip(".")
    if host.startswith("www."):
        host = host[4:]
    return any(host == domain or host.endswith(f".{domain}") for domain in _MANAGED_CLOUD_PROVIDER_DOMAINS)


def _redact_secret(value: str) -> str:
    if len(value) <= 8:
        return value[:2] + "..." if len(value) > 2 else value
    return f"{value[:4]}...{value[-4:]}"


def _encrypt_secret_material(value: str | None) -> str | None:
    if not value:
        return None
    from forge.utils.intel.secret_finder import _encrypt  # noqa: PLC0415

    return _encrypt(value)


_KEY_ENCRYPTION_UNAVAILABLE_DETAIL = (
    "artifact_queue_ingest: key material not persisted because "
    "FORGE_ENGAGEMENT_KEY is unavailable; set FORGE_ENGAGEMENT_KEY to enable validation"
)


def _encrypt_secret_material_for_finding(value: str) -> tuple[str | None, str | None]:
    try:
        return _encrypt_secret_material(value), None
    except RuntimeError:
        # Preserve the redacted finding for operator review without writing raw key material.
        return None, _KEY_ENCRYPTION_UNAVAILABLE_DETAIL


def _redact_azure_storage_connection_string(value: str) -> str:
    try:
        from forge.utils.intel.secret_finder import _parse_azure_storage_connection_string

        parts = _parse_azure_storage_connection_string(value)
    except Exception:  # noqa: BLE001
        return _redact_secret(value)

    protocol = str(parts.get("defaultendpointsprotocol") or "https").strip().lower() or "https"
    account_name = str(parts.get("accountname") or "").strip()
    if not account_name:
        return _redact_secret(value)
    return (
        f"DefaultEndpointsProtocol={protocol};"
        f"AccountName={account_name};"
        "AccountKey=<redacted>"
    )


def _normalize_phone_seed_value(value: Any) -> str:
    candidate = str(value or "").strip()
    if not candidate:
        return ""
    candidate = _PHONE_NORMALIZE_RE.sub("", candidate)
    if candidate.startswith("00") and len(candidate) > 3:
        candidate = f"+{candidate[2:]}"
    if candidate.startswith("+") and re.match(r"^\+\d{6,15}$", candidate):
        return candidate
    return ""


def _normalize_artifact_text_url(value: str) -> str:
    candidate = str(value or "").strip()
    if not candidate:
        return ""
    candidate = candidate.replace("\\/", "/")
    candidate = html.unescape(candidate)
    while candidate:
        previous = candidate
        candidate = _ARTIFACT_URL_ESCAPED_CONTROL_SUFFIX_RE.sub("", candidate)
        candidate = candidate.rstrip(")]}.,;\"'\\")
        if candidate == previous:
            break
    parsed = urlparse(candidate)
    if parsed.scheme.lower() in {"http", "https"} and parsed.hostname and "@" in parsed.netloc:
        hostname = parsed.hostname.lower()
        if ":" in hostname and not hostname.startswith("["):
            hostname = f"[{hostname}]"
        try:
            port = parsed.port
        except ValueError:
            port = None
        netloc = f"{hostname}:{port}" if port else hostname
        candidate = parsed._replace(netloc=netloc).geturl()
        parsed = urlparse(candidate)
    if parsed.scheme.lower() in {"http", "https"} and parsed.query:
        safe_query_pairs = [
            (key, value)
            for key, value in parse_qsl(parsed.query, keep_blank_values=True)
            if not _artifact_url_query_key_is_sensitive(key)
        ]
        safe_query = urlencode(safe_query_pairs, doseq=True)
        candidate = parsed._replace(query=safe_query).geturl()
    return candidate


def _artifact_url_looks_templated(value: object) -> bool:
    candidate = str(value or "")
    decoded = unquote(candidate)
    return any(
        marker in text
        for text in (candidate, decoded)
        for marker in ("{", "}", "${", "$(", "{{", "}}", "<", ">")
    )


def _artifact_url_looks_standards_namespace(value: object) -> bool:
    parsed = urlparse(str(value or "").strip())
    host = str(parsed.hostname or "").strip().lower().rstrip(".")
    path = unquote(str(parsed.path or "")).lower()
    return (
        (host == "docs.oasis-open.org" and path.startswith("/ns/"))
        or (host == "www.w3.org" and path.startswith("/ns/"))
        or (host == "www.w3.org" and path in {"/2005/atom"})
        or (host == "w3.org" and path.startswith("/ns/"))
        or (host == "w3.org" and path in {"/2005/atom"})
        or (host == "jsonfeed.org" and path.startswith("/version/"))
        or (host == "nodeinfo.diaspora.software" and path.startswith("/ns/schema/"))
        or (host == "search.yahoo.com" and path in {"/mrss/"})
    )


def _normalize_artifact_network_dsn_token(value: str) -> str:
    candidate = str(value or "").strip().replace("\\/", "/")
    if not candidate:
        return ""
    while candidate:
        previous = candidate
        candidate = _ARTIFACT_URL_ESCAPED_CONTROL_SUFFIX_RE.sub("", candidate)
        candidate = candidate.rstrip(")]}.,;\"'`\\")
        if candidate == previous:
            break
    if candidate.lower().startswith("jdbc:"):
        candidate = candidate[5:]
    return candidate


def _artifact_network_host_seed_entries_for_host(hostname: str) -> list[tuple[str, str]]:
    hostname = str(hostname or "").strip().lower().strip(".")
    if not hostname or hostname in {"localhost", "localhost.localdomain"}:
        return []
    entries: list[tuple[str, str]] = []
    try:
        parsed_ip = ipaddress.ip_address(hostname)
    except ValueError:
        parsed_ip = None
    if parsed_ip is not None:
        normalized_ip = str(parsed_ip)
        if _is_placeholder_host_ip(normalized_ip):
            return []
        return [(normalized_ip, "ipv6" if parsed_ip.version == 6 else "ipv4")]
    if _classify_seed_value(hostname) != "domain":
        return []
    if _is_social_platform_host(hostname):
        return []
    root_domain = _normalize_root_domain(hostname)
    if hostname == root_domain:
        entries.append((root_domain, "domain"))
    else:
        entries.append((hostname, "subdomain"))
        if root_domain and _classify_seed_value(root_domain) == "domain":
            entries.append((root_domain, "domain"))
    return entries


def _artifact_network_host_seed_entries(value: str) -> list[tuple[str, str]]:
    oracle_jdbc_match = _ARTIFACT_ORACLE_JDBC_DSN_RE.search(str(value or ""))
    if oracle_jdbc_match:
        return _artifact_network_host_seed_entries_for_host(
            oracle_jdbc_match.group("host")
        )
    candidate = _normalize_artifact_network_dsn_token(value)
    parsed = urlparse(candidate)
    if parsed.scheme.lower() not in _ARTIFACT_NETWORK_DSN_SCHEMES or not parsed.hostname:
        return []
    return _artifact_network_host_seed_entries_for_host(parsed.hostname)


def _artifact_network_dsn_seed_entries(value: str) -> list[tuple[str, str]]:
    return _artifact_network_host_seed_entries(value)


def _looks_like_ssh_public_key_type(value: str) -> bool:
    lowered = str(value or "").strip().lower()
    return lowered.startswith(
        (
            "ecdsa-sha2-",
            "rsa-sha2-",
            "sk-ecdsa-",
            "sk-ssh-",
            "ssh-dss",
            "ssh-ed25519",
            "ssh-rsa",
        )
    )


def _normalize_ssh_known_host_token(value: str) -> str:
    candidate = str(value or "").strip().strip(",")
    if not candidate or candidate.startswith("|"):
        return ""
    if candidate.startswith("["):
        bracket_match = re.match(r"^\[([^\]]+)\](?::\d+)?$", candidate)
        candidate = bracket_match.group(1) if bracket_match else candidate
    elif candidate.count(":") == 1:
        host_part, port_part = candidate.rsplit(":", 1)
        if port_part.isdigit():
            candidate = host_part
    candidate = candidate.strip().lower().strip(".")
    if candidate.startswith("*."):
        candidate = candidate[2:]
    if not candidate or candidate in {"*", "?"}:
        return ""
    if any(marker in candidate for marker in ("%", "$", "{", "}", "!", "?")):
        return ""
    return candidate


def _ssh_known_host_token_seed_entries(raw_host: str) -> list[tuple[str, str]]:
    candidate = _normalize_ssh_known_host_token(raw_host)
    if not candidate:
        return []
    return _artifact_network_host_seed_entries_for_host(candidate)


def _ssh_known_host_line_tokens(raw_line: str) -> list[str]:
    line = str(raw_line or "").split("#", 1)[0].strip()
    if not line:
        return []
    tokens = line.split()
    if len(tokens) < 3:
        return []
    host_index = 0
    if tokens[0].startswith("@"):
        host_index = 1
    key_type_index = host_index + 1
    if key_type_index >= len(tokens) or not _looks_like_ssh_public_key_type(tokens[key_type_index]):
        return []
    host_field = tokens[host_index]
    if host_field.startswith("|"):
        return []
    return [host_token for host_token in host_field.split(",") if host_token]


def _extract_artifact_ssh_host_seeds(text: str) -> list[tuple[str, str]]:
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    line_token_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        str(text or "").splitlines(),
        _ssh_known_host_line_tokens,
        default_factory=list,
    )
    host_tokens: list[str] = []
    for line_token_batch in line_token_batches:
        host_tokens.extend(line_token_batch)
    for match in _ARTIFACT_SSH_HOSTNAME_RE.finditer(str(text or "")):
        host_tokens.append(match.group("host"))
    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        host_tokens,
        _ssh_known_host_token_seed_entries,
        default_factory=list,
    )
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _remote_access_host_field_seed_entries(raw_value: str) -> list[tuple[str, str]]:
    candidate = str(raw_value or "").strip().strip("\"'")
    if not candidate or "://" in candidate or "\\" in candidate or "@" in candidate:
        return []
    tokens = [
        token.strip().strip("\"'[](){}.,;")
        for token in re.split(r"[\s,]+", candidate)
        if token.strip()
    ]
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for token in tokens:
        if not token or "/" in token:
            continue
        for seed in _ssh_known_host_token_seed_entries(token):
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _extract_artifact_remote_access_host_seeds(text: str) -> list[tuple[str, str]]:
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [
            match.group("value")
            for match in _ARTIFACT_REMOTE_ACCESS_HOST_FIELD_RE.finditer(str(text or ""))
        ],
        _remote_access_host_field_seed_entries,
        default_factory=list,
    )
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _normalize_dns_zone_host_token(value: str, *, origin: str = "") -> str:
    candidate = str(value or "").strip().strip("\"'()")
    if not candidate:
        return ""
    candidate = candidate.rstrip(",")
    if candidate in {"@", "."}:
        return origin.strip(".")
    if any(marker in candidate for marker in ("$", "{", "}", "/", "\\")):
        return ""
    if ":" in candidate:
        return ""
    had_trailing_dot = candidate.endswith(".")
    candidate = candidate.rstrip(".").lower()
    if not candidate or candidate == "localhost":
        return ""
    if candidate.startswith("*."):
        candidate = candidate[2:]
    if origin and not had_trailing_dot and "." not in candidate:
        candidate = f"{candidate}.{origin.strip('.')}"
    return candidate.strip(".")


def _dns_zone_line_host_tokens(raw_line: str, *, origin: str) -> list[str]:
    line = str(raw_line or "").split(";", 1)[0].strip()
    if not line or line.startswith("$"):
        return []
    tokens = [
        token.strip().strip("\"'()")
        for token in line.split()
        if token.strip().strip("\"'()")
    ]
    if len(tokens) < 2:
        return []
    type_index = -1
    for index, token in enumerate(tokens):
        if token.upper() in _DNS_ZONE_RECORD_TYPES:
            type_index = index
            break
    if type_index <= 0:
        return []

    owner_token = tokens[0]
    record_type = tokens[type_index].upper()
    data_tokens = tokens[type_index + 1 :]
    host_tokens: list[str] = []
    owner_host = _normalize_dns_zone_host_token(owner_token, origin=origin)
    if owner_host:
        host_tokens.append(owner_host)

    if record_type in {"CNAME", "NS", "PTR"} and data_tokens:
        host_tokens.append(_normalize_dns_zone_host_token(data_tokens[0], origin=origin))
    elif record_type == "MX" and len(data_tokens) >= 2:
        host_tokens.append(_normalize_dns_zone_host_token(data_tokens[1], origin=origin))
    elif record_type == "SOA" and data_tokens:
        host_tokens.append(_normalize_dns_zone_host_token(data_tokens[0], origin=origin))
    elif record_type == "SRV" and len(data_tokens) >= 4:
        host_tokens.append(_normalize_dns_zone_host_token(data_tokens[3], origin=origin))

    return [host for host in host_tokens if host]


def _dns_zone_line_host_token_entry(entry: tuple[str, str]) -> list[str]:
    raw_line, origin = entry
    return _dns_zone_line_host_tokens(raw_line, origin=origin)


def _extract_artifact_dns_zone_host_seeds(text: str) -> list[tuple[str, str]]:
    raw_text = str(text or "")
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    host_tokens: list[str] = []
    origin = ""
    ordered_line_items: list[tuple[str, str | tuple[str, str]]] = []

    for match in _ARTIFACT_BIND_ZONE_DECLARATION_RE.finditer(raw_text):
        host = _normalize_dns_zone_host_token(match.group("zone"), origin="")
        if host:
            host_tokens.append(host)

    for raw_line in raw_text.splitlines():
        origin_match = _ARTIFACT_DNS_ORIGIN_RE.match(raw_line)
        if origin_match:
            origin = _normalize_dns_zone_host_token(origin_match.group("origin"), origin="")
            if origin:
                ordered_line_items.append(("host", origin))
            continue
        ordered_line_items.append(("line", (raw_line, origin)))

    line_token_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [
            payload
            for item_type, payload in ordered_line_items
            if item_type == "line" and isinstance(payload, tuple)
        ],
        _dns_zone_line_host_token_entry,
        default_factory=list,
    )
    line_batch_index = 0
    for item_type, payload in ordered_line_items:
        if item_type == "host" and isinstance(payload, str):
            host_tokens.append(payload)
            continue
        if item_type == "line":
            if line_batch_index < len(line_token_batches):
                host_tokens.extend(line_token_batches[line_batch_index])
            line_batch_index += 1

    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        host_tokens,
        _artifact_network_host_seed_entries_for_host,
        default_factory=list,
    )
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _hosts_file_line_host_tokens(raw_line: str) -> list[str]:
    line = str(raw_line or "").split("#", 1)[0].strip()
    if not line:
        return []
    tokens = [token.strip() for token in line.split() if token.strip()]
    if len(tokens) < 2:
        return []
    try:
        parsed_ip = ipaddress.ip_address(tokens[0])
    except ValueError:
        return []
    if parsed_ip.is_loopback or parsed_ip.is_link_local or parsed_ip.is_multicast:
        return []
    if _is_placeholder_host_ip(str(parsed_ip)):
        return []

    host_tokens: list[str] = []
    for token in tokens[1:]:
        candidate = token.strip().strip("\"'[](){}.,;").lower().strip(".")
        if not candidate or candidate in {"localhost", "localhost.localdomain"}:
            continue
        if candidate.startswith(("ip6-", "broadcasthost")):
            continue
        if any(marker in candidate for marker in ("*", "?", "$", "{", "}", "/", "\\")):
            continue
        host_tokens.append(candidate)
    return host_tokens


def _extract_artifact_hosts_file_host_seeds(text: str) -> list[tuple[str, str]]:
    host_tokens: list[str] = []
    line_token_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        str(text or "").splitlines(),
        _hosts_file_line_host_tokens,
        default_factory=list,
    )
    for line_token_batch in line_token_batches:
        host_tokens.extend(line_token_batch)
    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        host_tokens,
        _artifact_network_host_seed_entries_for_host,
        default_factory=list,
    )
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _looks_like_lease_mac_token(value: str) -> bool:
    return re.fullmatch(r"(?:[0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}", str(value or "").strip()) is not None


def _normalize_dhcp_lease_host_token(value: str) -> str:
    candidate = str(value or "").strip().strip("\"'[](){}.,;").lower().strip(".")
    if not candidate or candidate in {"*", "-", "localhost", "localhost.localdomain"}:
        return ""
    if candidate.startswith(("ip6-", "broadcasthost")):
        return ""
    if any(marker in candidate for marker in ("?", "$", "{", "}", "/", "\\", "@", ":")):
        return ""
    if _looks_like_lease_mac_token(candidate):
        return ""
    try:
        ipaddress.ip_address(candidate)
        return ""
    except ValueError:
        pass
    return candidate


def _dhcp_lease_line_host_tokens(raw_line: str) -> list[str]:
    line = str(raw_line or "").split("#", 1)[0].strip()
    if not line:
        return []
    if "," in line:
        cells = [cell.strip().strip("\"'") for cell in line.split(",")]
        if not cells or cells[0].lower() in {"address", "ip", "ip_address"}:
            return []
        ip_index = -1
        for index, cell in enumerate(cells):
            try:
                ipaddress.ip_address(cell)
            except ValueError:
                continue
            ip_index = index
            break
        if ip_index < 0:
            return []
        return [
            host
            for host in (_normalize_dhcp_lease_host_token(cell) for cell in cells[ip_index + 1 :])
            if host
        ]

    tokens = [token.strip() for token in line.split() if token.strip()]
    if len(tokens) >= 4 and tokens[0].isdigit() and _looks_like_lease_mac_token(tokens[1]):
        try:
            ipaddress.ip_address(tokens[2])
        except ValueError:
            return []
        host = _normalize_dhcp_lease_host_token(tokens[3])
        return [host] if host else []
    return []


def _extract_artifact_dhcp_lease_host_seeds(text: str) -> list[tuple[str, str]]:
    raw_text = str(text or "")
    host_tokens = [
        _normalize_dhcp_lease_host_token(match.group("host"))
        for match in _ARTIFACT_DHCP_LEASE_HOST_FIELD_RE.finditer(raw_text)
    ]
    line_token_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        raw_text.splitlines(),
        _dhcp_lease_line_host_tokens,
        default_factory=list,
    )
    for line_token_batch in line_token_batches:
        host_tokens.extend(line_token_batch)

    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [host for host in host_tokens if host],
        _artifact_network_host_seed_entries_for_host,
        default_factory=list,
    )
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


