def _borg_text_config_artifact_kind(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    segments = [segment for segment in normalized.split("/") if segment]
    if not segments:
        return ""
    name = segments[-1]
    parent_segments = set(segments[:-1])
    if name == "borg.location" or re.fullmatch(r"\d+-borg\.location", name):
        return "location"
    if name == "borg.key-type" or re.fullmatch(r"\d+-borg\.key-type", name):
        return "key_type"
    if name == "borg.repository.config" or re.fullmatch(r"\d+-borg\.repository\.config", name):
        return "repository_config"
    if name in {"location", "key-type"} and "security" in parent_segments and (
        {"borg", ".borg"} & parent_segments
    ):
        return "location" if name == "location" else "key_type"
    if name == "config" and ({"borg", ".borg"} & parent_segments):
        return "repository_config"
    return ""


