def _ansible_inventory_line_host_tokens(raw_line: str) -> list[str]:
    line = str(raw_line or "").split("#", 1)[0].strip()
    if not line:
        return []
    if line.startswith(("[", "---", "...")):
        return []
    host_tokens: list[str] = []
    mapping_match = re.match(
        r"""^\s*["']?(?P<host>[A-Za-z0-9_.-]+\.?[A-Za-z0-9-]*)["']?\s*:\s*(?:[{\[]?.*)?$""",
        line,
    )
    if mapping_match:
        host_tokens.append(mapping_match.group("host"))
    else:
        first_token = line.split(None, 1)[0].strip().strip("\"'[]{}(),;")
        if first_token and "=" not in first_token and ":" not in first_token:
            host_tokens.append(first_token)
    host_tokens.extend(
        match.group("value").strip().strip("\"'")
        for match in _ARTIFACT_ANSIBLE_HOST_FIELD_RE.finditer(line)
    )
    return [token for token in host_tokens if token]


def _extract_artifact_ansible_inventory_host_seeds(text: str) -> list[tuple[str, str]]:
    host_token_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        str(text or "").splitlines(),
        _ansible_inventory_line_host_tokens,
        default_factory=list,
    )
    host_tokens: list[str] = []
    for host_token_batch in host_token_batches:
        host_tokens.extend(host_token_batch)
    seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        host_tokens,
        _remote_access_host_field_seed_entries,
        default_factory=list,
    )
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for seed_batch in seed_batches:
        for seed in seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


