def _looks_like_terraform_state_name(value: str) -> bool:
    lowered = Path(str(value or "").strip()).name.lower()
    if not lowered:
        return False
    return (
        lowered == "terraform.tfstate"
        or lowered.endswith(".tfstate")
        or lowered.endswith(".tfstate.backup")
        or lowered.endswith(".tfstate.json")
    )


def _looks_like_terraform_backend_config_name(value: str) -> bool:
    lowered = Path(str(value or "").strip().replace("\\", "/")).name.lower()
    if not lowered:
        return False
    return lowered.endswith(".tfbackend") or lowered in {
        "backend.hcl",
        "backend.tfbackend",
        "terraform.backend.hcl",
        "tofu.backend.hcl",
    }


def _looks_like_terragrunt_config_name(value: str) -> bool:
    lowered = Path(str(value or "").strip().replace("\\", "/")).name.lower()
    return lowered == "terragrunt.hcl"


def _looks_like_browser_sqlite_artifact_name(value: str) -> bool:
    lowered = Path(str(value or "").strip().replace("\\", "/")).name.lower()
