_EDGE_PROXY_STRUCTURED_LABELS = {
    "apache-config",
    "caddyfile",
    "envoy-config",
    "haproxy-config",
    "kong-config",
    "nginx-config",
    "traefik-config",
}
_EDGE_PROXY_HOST_RULE_RE = re.compile(r"\bHost(?:SNI)?\s*\((?P<values>[^)]{1,2048})\)", re.IGNORECASE)
_EDGE_PROXY_HOST_RULE_VALUE_RE = re.compile(
    r"""[`'"](?P<quoted>[^`'"]{1,512})[`'"]|(?P<bare>[A-Za-z0-9*_.-]+(?::\d{1,5})?)""",
    re.IGNORECASE,
)
_EDGE_PROXY_HOST_TOKEN_RE = (
    r"(?:(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}|"
    r"(?:\d{1,3}\.){3}\d{1,3})"
)
_EDGE_PROXY_ENDPOINT_TOKEN_RE = re.compile(
    rf"""
    (?:
        (?:https?|wss?|ws|grpc|grpcs|h2c)://[^\s"'`),;\]}}]+
        |//{_EDGE_PROXY_HOST_TOKEN_RE}(?::\d{{1,5}})?(?:/[^\s"'`),;\]}}]*)?
        |{_EDGE_PROXY_HOST_TOKEN_RE}(?::\d{{1,5}})?(?:/[^\s"'`),;\]}}]*)?
    )
    """,
    re.IGNORECASE | re.VERBOSE,
)
_EDGE_PROXY_KEYED_VALUE_RE = re.compile(
    r"""
    ^\s*(?:-\s*)?
    (?P<key>
        proxy_pass|fastcgi_pass|uwsgi_pass|scgi_pass|grpc_pass|
        reverse_proxy|proxypass|proxypassreverse|
        to|url|urls|address|addresses|host|hosts|hostname|
        server_name|servername|serveralias|server|servers|
        target|targets|endpoint|endpoints|service_url|upstream_url|backend_url
    )
    \b\s*(?:[:=]\s*)?(?P<value>.+?)\s*$
    """,
    re.IGNORECASE | re.VERBOSE,
)


