def _security_scanner_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = tuple(part for part in normalized.split("/") if part)
    if len(parts) >= 2 and parts[-1] == parts[-2]:
        parts = parts[:-1]
