def _api_spec_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    name = Path(normalized).name
    if not name:
        return ""
    if name in {"api-docs", "api_docs", "v3-api-docs", "v3_api_docs"}:
        return "openapi"
    if name in {"openapi", "swagger", "asyncapi", "arazzo"}:
        return name
    if name in {"api-blueprint", "api_blueprint", "apiary"}:
        return "api-blueprint"
    if name.endswith((".apib", ".api-blueprint", ".api_blueprint")):
        return "api-blueprint"
    if name.endswith(".arazzo"):
        return "arazzo"
    if name in {"openapi-overlay", "openapi_overlay"}:
        return "openapi-overlay"
    if name.endswith((".openapi-overlay", ".openapi_overlay")):
        return "openapi-overlay"
    for spec_label in ("openapi", "swagger", "asyncapi"):
        if name.endswith(f".{spec_label}"):
            return spec_label
    stem = name
    for suffix in (".json", ".jsonc", ".yaml", ".yml"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
            break
    if stem in {"api-docs", "api_docs", "v3-api-docs", "v3_api_docs"}:
        return "openapi"
    if stem in {"api-blueprint", "api_blueprint", "apiary"}:
        return "api-blueprint"
    if stem in {"arazzo", "arazzo-spec", "arazzo_spec"}:
        return "arazzo"
    if stem in {"openapi-overlay", "openapi_overlay", "openapi-overlay-spec", "openapi_overlay_spec"}:
        return "openapi-overlay"
    if stem == "overlay" and any(part in normalized for part in ("openapi", "oas")):
        return "openapi-overlay"
    if stem in {"openapi", "openapi-spec", "openapi_spec", "swagger", "asyncapi"}:
        return "openapi" if stem.startswith("openapi") else stem
    return ""


def _api_client_collection_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    name = Path(normalized).name
    if not name:
        return ""
    pact_label = pact_contract_artifact_label(normalized)
    if pact_label:
        return pact_label
    if name in {"locustfile", "locustfile.py", "locust.conf"} or name.startswith("locustfile."):
        return "locustfile"
    script_suffixes = (".js", ".mjs", ".cjs", ".ts", ".mts", ".cts")
    if name.endswith(script_suffixes):
        script_stem = name
        while Path(script_stem).suffix.lower() in script_suffixes:
            script_stem = Path(script_stem).stem
        if "k6" in {token for token in re.split(r"[^a-z0-9]+", script_stem) if token}:
            return "k6-script"
        if "pactum" in {token for token in re.split(r"[^a-z0-9]+", script_stem) if token}:
            return "pactum-config"
    if name.endswith(".feature"):
        return "gherkin-feature"
    if name.endswith(".jmx"):
        return "jmeter-test-plan"
    if name.endswith(".side"):
        return "selenium-side"
    if name.endswith((".tavern.yaml", ".tavern.yml")) or name in {"tavern.yaml", "tavern.yml"}:
        return "tavern-api-test"
    if name in {
        ".dredd.json",
        ".dredd.yaml",
        ".dredd.yml",
        "dredd.json",
        "dredd.yaml",
        "dredd.yml",
    }:
        return "dredd-config"
    if name in {
        ".schemathesis.json",
        ".schemathesis.toml",
        ".schemathesis.yaml",
        ".schemathesis.yml",
        "schemathesis.json",
        "schemathesis.toml",
        "schemathesis.yaml",
        "schemathesis.yml",
    }:
        return "schemathesis-config"
    if name in {
        ".pactumrc",
        ".pactumrc.json",
        ".pactumrc.yaml",
        ".pactumrc.yml",
        "pactum.config.json",
        "pactum.config.yaml",
        "pactum.config.yml",
    }:
        return "pactum-config"
    if name in {"pyresttest.yaml", "pyresttest.yml", "resttest.yaml", "resttest.yml"} or name.endswith(
        (".pyresttest.yaml", ".pyresttest.yml", ".resttest.yaml", ".resttest.yml")
    ):
        return "pyresttest"
    if name in {"postman_collection", "postman-collection"} or name.endswith(
        (".postman_collection", ".postman-collection")
    ):
        return "postman-collection"
    if name in {"postman_environment", "postman-environment"} or name.endswith(
        (".postman_environment", ".postman-environment")
    ):
        return "postman-environment"
    if name in {"insomnia_collection", "insomnia-collection"} or name.endswith(
        (".insomnia_collection", ".insomnia-collection")
    ):
        return "insomnia-collection"
    if name in {"insomnia_environment", "insomnia-environment"} or name.endswith(
        (".insomnia_environment", ".insomnia-environment")
    ):
        return "insomnia-environment"
    if name.endswith(".bru"):
        return "bruno"
    stem = name
    for suffix in (".json", ".toml", ".yaml", ".yml"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
            break
    if "postman" in stem and "collection" in stem:
        return "postman-collection"
    if "postman" in stem and "environment" in stem:
        return "postman-environment"
    if "insomnia" in stem and ("collection" in stem or "export" in stem):
        return "insomnia-collection"
    if "insomnia" in stem and "environment" in stem:
        return "insomnia-environment"
    if "hoppscotch" in stem and ("collection" in stem or stem == "hoppscotch"):
        return "hoppscotch-collection"
    if "hoppscotch" in stem and "environment" in stem:
        return "hoppscotch-environment"
    if "thunder" in stem and "environment" in stem:
        return "thunder-client-environment"
    if "thunder" in stem and ("collection" in stem or "client" in stem):
        return "thunder-client-collection"
    if "selenium" in stem and any(marker in stem for marker in ("side", "project", "suite")):
        return "selenium-side"
    if "tavern" in stem and any(marker in stem for marker in ("api", "test", "suite", "requests")):
        return "tavern-api-test"
    if stem in {"dredd", ".dredd"}:
        return "dredd-config"
    if stem in {"schemathesis", ".schemathesis"}:
        return "schemathesis-config"
    if "pactum" in stem and any(marker in stem for marker in ("config", "api", "test", "suite")):
        return "pactum-config"
    if "pyresttest" in stem or (
        "resttest" in stem and any(marker in stem for marker in ("api", "test", "suite", "requests"))
    ):
        return "pyresttest"
    if ("soapui" in stem or "readyapi" in stem) and any(
        marker in stem for marker in ("project", "workspace", "collection", "export")
    ):
        return "soapui-project"
    if stem in {"artillery", ".artilleryrc"} or (
        "artillery" in stem and any(marker in stem for marker in ("config", "load", "test"))
    ):
        return "artillery-config"
    return ""


