def _table_exists(con: sqlite3.Connection, table_name: str) -> bool:
    try:
        row = con.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
            (table_name,),
        ).fetchone()
    except sqlite3.OperationalError:
        return False
    return row is not None


def _table_columns(con: sqlite3.Connection, table_name: str) -> set[str]:
    try:
        rows = con.execute(f"PRAGMA table_info({table_name})").fetchall()
    except sqlite3.OperationalError:
        return set()
    columns: set[str] = set()
    for row in rows:
        try:
            columns.add(str(row[1]))
        except Exception:  # noqa: BLE001
            continue
    return columns


@dataclass
class EmailPartExtractionJob:
    source_file: str
    member_name: str
    depth: int
    payload_bytes: bytes | None = None
    nested_messages: list[tuple[str, bytes]] = field(default_factory=list)


@dataclass
class EmailPartPlanningEntry:
    payloads: list[tuple[str, str, str]] = field(default_factory=list)
    extraction_job: EmailPartExtractionJob | None = None


@dataclass
class SQLiteObjectExtractionJob:
    database_path: str
    source_file: str
    member_name: str
    object_name: str
    object_sql: str = ""


@dataclass
class OLEStreamExtractionJob:
    source_file: str
    member_name: str
    stream_name: str
    stream_data: bytes
    depth: int


@dataclass
class MsgOLEPropertyJob:
    source_file: str
    member_name: str
    attachment_storage: str
    label: str
    prop_id: str
    prop_type: str
    stream_data: bytes


@dataclass
class MsgOLEPropertyResult:
    payloads: list[tuple[str, str, str]] = field(default_factory=list)
    summary_lines: list[str] = field(default_factory=list)
    attachment_storage: str = ""
    attachment_updates: list[tuple[str, Any]] = field(default_factory=list)


@dataclass
class MsgAttachmentExtractionJob:
    source_file: str
    member_name: str
    attachment_name: str
    attachment_data: bytes
    depth: int


@dataclass
class HAREntryExtractionJob:
    source_file: str
    member_name: str
    entry_index: int
    entry: Any


@dataclass
class WARCRecordExtractionJob:
    source_file: str
    member_name: str
    record_index: int
    record: bytes


def _artifact_progress_snapshot(
    *,
    total: int,
    workers: int,
    completed: int,
    failed: int,
    started_at: float,
) -> dict[str, object]:
    return artifact_progress_snapshot(
        total=total,
        workers=workers,
        completed=completed,
        failed=failed,
        started_at=started_at,
    )


