    def _extract_social_profile_pivots(
        self,
        profile: dict[str, Any],
        *,
        source_label: str,
        platform: str,
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        base_confidence = self._social_profile_base_confidence(source_label, platform)
        verified = bool(profile.get("verified") or profile.get("is_verified"))
        if verified:
            base_confidence = min(0.92, base_confidence + 0.04)

        company_profile = self._social_profile_is_company_profile(
            profile,
            source_label=source_label,
            platform=platform,
        )
        return social_profile_pivots(
            profile,
            source_label=source_label,
            platform=platform,
            base_confidence=base_confidence,
            company_profile=company_profile,
            pivot_families=(
                "handles",
                "company",
                "name",
                "emails",
                "phones",
                "urls",
                "matrix_hosts",
                "federated_hosts",
                "hosts",
                "domain",
            ),
            pivot_family=self._social_profile_pivot_family,
            pivot_batch_entries=self._social_profile_pivot_batch_entries,
            pivot_family_entries=self._social_profile_pivot_family_entries,
            run_ordered_batch=self._run_ordered_local_batch,
        )

