    @staticmethod
    def _linkedin_app_profile_path_parts(parsed: Any) -> list[str]:
        if str(getattr(parsed, "scheme", "") or "").strip().lower() != "linkedin":
            return []
        parts = [
            part
            for part in [
                str(getattr(parsed, "netloc", "") or "").strip("/"),
                *str(getattr(parsed, "path", "") or "").strip("/").split("/"),
            ]
            if part
        ]
        if len(parts) < 2:
            return []
        if parts[0].lower() not in {"in", "pub", "profile", "company", "school", "showcase"}:
            return []
        return parts

    @staticmethod
    def _social_profile_handle_allowed_for_platform(platform: str, handle: str) -> bool:
        platform_text = str(platform or "").strip().lower()
        handle_text = str(handle or "").strip().lstrip("@").lower()
        if not platform_text or not handle_text:
            return True
        if EngagementSynthesisEngine._social_profile_platform_is_federated(platform_text):
            return handle_text not in _MASTODON_RESERVED_PROFILE_HANDLES
        if platform_text == "facebook":
            return handle_text not in _FACEBOOK_RESERVED_PROFILE_HANDLES
        if platform_text == "linkedin":
            return handle_text not in _LINKEDIN_RESERVED_PROFILE_HANDLES
        if platform_text == "instagram":
            return handle_text not in _INSTAGRAM_RESERVED_PROFILE_PATHS
        if platform_text in {"telegram", "telegramme"}:
            return handle_text not in _TELEGRAM_RESERVED_PROFILE_PATHS
        if platform_text == "tiktok":
            return handle_text not in _TIKTOK_RESERVED_PROFILE_HANDLES
        if platform_text == "youtube":
            return handle_text not in _YOUTUBE_RESERVED_PROFILE_HANDLES
        if platform_text in {"devto", "dev.to"}:
            return handle_text not in _DEVTO_RESERVED_PROFILE_PATHS
        if platform_text in {"google_scholar", "googlescholar", "scholar"}:
            return bool(
                handle_text not in _GOOGLE_SCHOLAR_RESERVED_PROFILE_HANDLES
                and
                EngagementSynthesisEngine._normalize_google_scholar_user_id_candidate(handle)
            )
        if platform_text in {"nostr", "nostr_protocol"}:
            return bool(
                handle_text not in _NOSTR_RESERVED_PROFILE_PATHS
                and EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(handle)
            )
        if platform_text in {"twitter", "x"}:
            return handle_text not in _TWITTER_RESERVED_PROFILE_PATHS
        if platform_text == "bitbucket":
            return handle_text not in _BITBUCKET_RESERVED_PROFILE_PATHS
        if platform_text == "codeberg":
            return handle_text not in _CODEBERG_RESERVED_PROFILE_PATHS
        if platform_text == "codepen":
            return handle_text not in _CODEPEN_RESERVED_PROFILE_HANDLES
        if platform_text == "github":
            return handle_text not in _GITHUB_RESERVED_PROFILE_PATHS
        if platform_text in {"github_gist", "githubgist", "gist"}:
            return handle_text not in _GITHUB_GIST_RESERVED_PROFILE_PATHS
        if platform_text == "gitlab":
            return handle_text not in _GITLAB_RESERVED_PROFILE_PATHS
        if platform_text == "hashnode":
            return handle_text not in _HASHNODE_RESERVED_PROFILE_PATHS
        if platform_text == "medium":
            return (
                handle_text not in _MEDIUM_RESERVED_PROFILE_PATHS
                and handle_text not in _MEDIUM_RESERVED_SUBDOMAINS
            )
        if platform_text == "substack":
            return (
                handle_text not in _SUBSTACK_RESERVED_PROFILE_PATHS
                and handle_text not in _SUBSTACK_RESERVED_SUBDOMAINS
            )
        if platform_text == "flickr":
            return handle_text not in _FLICKR_RESERVED_PHOTOS_PATHS
        if platform_text == "letterboxd":
            return handle_text not in _LETTERBOXD_RESERVED_PROFILE_PATHS
        if platform_text == "mixcloud":
            return handle_text not in _MIXCLOUD_RESERVED_PROFILE_PATHS
        if platform_text in {"slideshare", "slide_share"}:
            return handle_text not in _SLIDESHARE_RESERVED_PROFILE_PATHS
        if platform_text in {"soundcloud", "sound_cloud"}:
            return handle_text not in _SOUNDCLOUD_RESERVED_PROFILE_PATHS
        if platform_text in {"speakerdeck", "speaker_deck"}:
            return handle_text not in _SPEAKERDECK_RESERVED_PROFILE_PATHS
        if platform_text == "vimeo":
            return handle_text not in _VIMEO_RESERVED_PROFILE_PATHS
        if platform_text == "keybase":
            return handle_text not in _KEYBASE_RESERVED_PROFILE_PATHS
        if platform_text == "orcid":
            return bool(_ORCID_PROFILE_ID_RE.fullmatch(handle_text))
        reserved_direct_handles = _DIRECT_HANDLE_RESERVED_PROFILE_PATHS_BY_PLATFORM.get(platform_text)
        if reserved_direct_handles:
            return handle_text not in reserved_direct_handles
        return True

    @staticmethod
    def _social_profile_platform_is_federated(platform: str) -> bool:
        return str(platform or "").strip().lower() in {
            "activity_pub",
            "activitypub",
            "fediverse",
            "mastodon",
            "mastodon_social",
            "webfinger",
        }

    @staticmethod
    def _social_profile_base_confidence(source_label: str, platform: str) -> float:
        text = f"{source_label} {platform}".lower()
        if "linkedin" in text or "crosslinked" in text:
            return 0.8
        if "instagram" in text:
            return 0.79
        if "gravatar" in text:
            return 0.77
        if "ghunt" in text or "google" in text:
            return 0.76
        if "name_search" in text:
            return 0.73
        if "phone_dork" in text:
            return 0.72
        return 0.74

