    def __init__(
        self,
        db_path: Path,
        engagement_id: int,
        age_pubkey: str | None = None,
        *,
        max_workers: int | None = None,
        remote_url_scope_checker: Callable[[str], bool] | None = None,
        remote_scope_denied_callback: Callable[[ArtifactDownloadRequest, str], None] | None = None,
    ) -> None:
        self._db_path = db_path
        self._engagement_id = engagement_id
        self._extractor = FirebaseExtractor(age_pubkey=age_pubkey)
        self._ocr_binary = shutil.which("tesseract")
        self._pdf_raster_binary = shutil.which("pdftoppm") or shutil.which("pdftocairo")
        self._barcode_decoder_backends = barcode_decoder_backend_names()
        self._remote_url_scope_checker = remote_url_scope_checker
        self._remote_scope_denied_callback = remote_scope_denied_callback
        resolved_workers = 2 if max_workers is None else int(max_workers)
        self._max_workers = max(1, min(4, resolved_workers))
        try:
            from forge.utils.intel.secret_finder import load_key_patterns

            self._artifact_key_patterns = [
                pattern
                for pattern in load_key_patterns()
                if pattern.service != "unknown" and pattern.name != "generic_bearer_token"
            ]
        except Exception:  # noqa: BLE001
            self._artifact_key_patterns = []

    def set_remote_scope_gate(
        self,
        checker: Callable[[str], bool] | None,
        denied_callback: Callable[[ArtifactDownloadRequest, str], None] | None = None,
    ) -> None:
        self._remote_url_scope_checker = checker
        self._remote_scope_denied_callback = denied_callback

