    @staticmethod
    def _key_value_structured_candidate_jobs(
        env_map: dict[str, str],
        section_maps: dict[tuple[str, ...], dict[str, str]],
    ) -> list[tuple[str, tuple[str, ...], dict[str, str]]]:
        source_jobs: list[tuple[str, tuple[str, ...], dict[str, str]]] = []
        if env_map:
            source_jobs.append(("env", (), env_map))
        for section_path, mapping in section_maps.items():
            source_jobs.append(("section", section_path, mapping))
        return source_jobs

    @staticmethod
    def _key_value_structured_candidate_job(
        source_job: tuple[str, tuple[str, ...], dict[str, str]],
    ) -> tuple[str, tuple[str, ...], dict[str, str]] | None:
        family, section_path, mapping = source_job
        if family not in {"env", "section"}:
            return None
        return family, tuple(section_path), dict(mapping)

    def _key_value_structured_candidate_batch(
        self,
        job: tuple[str, tuple[str, ...], dict[str, str]],
    ) -> list[str]:
        family, section_path, mapping = job
        if family == "env":
            return self._yaml_structured_candidates_from_env_map(mapping)
        if family == "section":
            return self._yaml_map_structured_candidates(mapping, section_path)
        return []

    @staticmethod
    def _key_value_structured_candidate_family_entries(
        candidate_family: tuple[int, Sequence[str]],
    ) -> list[str]:
        _family_index, family = candidate_family
        return [candidate for candidate in family]

