    def _yaml_structured_payload_text(self, text: str, *, source_hint: str = "") -> str:
        if yaml is None:
            return ""
        try:
            documents = list(yaml.safe_load_all(text))
        except Exception:  # noqa: BLE001
            return ""

        line_batches = self._run_ordered_local_batch(
            documents,
            lambda document: self._structured_document_lines(
                document,
                source_hint=source_hint,
            ),
            default_factory=list,
        )
        prepared_line_batches = self._run_ordered_local_batch(
            list(enumerate(line_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for line_batch in prepared_line_batches:
            for candidate in line_batch:
                lowered = candidate.lower()
                if not candidate or lowered in seen:
                    continue
                seen.add(lowered)
                lines.append(candidate)
        return "\n".join(lines)

    def _structured_document_lines(self, document: Any, *, source_hint: str = "") -> list[str]:
        lines: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            lowered = candidate.lower()
            if not candidate or lowered in seen:
                return
            seen.add(lowered)
            lines.append(candidate)

        self._collect_yaml_structured_payload_lines(document, (), _append, source_hint=source_hint)
        return lines

    @staticmethod
    def _yaml_decode_secretish_value(value: Any) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (int, float)):
            return str(value).strip()
        text = str(value or "").strip()
        decoded = ArtifactQueueProcessor._yaml_try_decode_base64_text(text)
        return decoded or text

    @staticmethod
    def _yaml_try_decode_base64_text(value: str) -> str:
        candidate = str(value or "").strip()
        if len(candidate) < 8:
            return ""
        compact = re.sub(r"\s+", "", candidate)
        if len(compact) < 8 or len(compact) % 4 != 0:
            return ""
        if not re.fullmatch(r"[A-Za-z0-9+/]+={0,2}", compact):
            return ""
        try:
            decoded_bytes = base64.b64decode(compact, validate=True)
        except Exception:  # noqa: BLE001
            return ""
        if not decoded_bytes:
            return ""
        try:
            decoded = decoded_bytes.decode("utf-8").strip()
        except UnicodeDecodeError:
            return ""
        if not decoded or not any(char.isalnum() for char in decoded):
            return ""
        printable = sum(1 for char in decoded if char.isprintable() or char in "\r\n\t")
        if printable / max(1, len(decoded)) < 0.95:
            return ""
        return decoded

    def _yaml_env_map(self, entries: list[Any]) -> dict[str, str]:
        env_map: dict[str, str] = {}
        normalized_batches = self._run_ordered_local_batch(
            entries,
            self._yaml_env_entry,
            default_factory=list,
        )
        prepared_entry_batches = self._run_ordered_local_batch(
            list(enumerate(normalized_batches)),
            self._yaml_env_map_batch_entries,
            default_factory=list,
        )
        prepared_entry_families = self._run_ordered_local_batch(
            list(enumerate(prepared_entry_batches)),
            self._yaml_env_map_family_entries,
            default_factory=list,
        )
        prepared_write_entries = self._run_ordered_local_batch(
            [
                (entry_index, entry)
                for entry_index, entry in enumerate(
                    entry
                    for family in prepared_entry_families
                    for entry in family
                )
            ],
            self._yaml_env_map_write_entry,
            default_factory=lambda: None,
        )
        for write_entry in prepared_write_entries:
            if not isinstance(write_entry, tuple) or len(write_entry) != 3:
                continue
            env_name, env_value, alias_key = write_entry
            env_map[env_name] = env_value
            if alias_key:
                env_map.setdefault(alias_key, env_value)
        return env_map

    def _yaml_env_mapping(self, entries: dict[str, Any]) -> dict[str, str]:
        env_map: dict[str, str] = {}
        normalized_batches = self._run_ordered_local_batch(
            list(entries.items()),
            self._yaml_env_mapping_entry,
            default_factory=list,
        )
        prepared_entry_batches = self._run_ordered_local_batch(
            list(enumerate(normalized_batches)),
            self._yaml_env_map_batch_entries,
            default_factory=list,
        )
        prepared_entry_families = self._run_ordered_local_batch(
            list(enumerate(prepared_entry_batches)),
            self._yaml_env_map_family_entries,
            default_factory=list,
        )
        prepared_write_entries = self._run_ordered_local_batch(
            [
                (entry_index, entry)
                for entry_index, entry in enumerate(
                    entry
                    for family in prepared_entry_families
                    for entry in family
                )
            ],
            self._yaml_env_map_write_entry,
            default_factory=lambda: None,
        )
        for write_entry in prepared_write_entries:
            if not isinstance(write_entry, tuple) or len(write_entry) != 3:
                continue
            env_name, env_value, alias_key = write_entry
            env_map[env_name] = env_value
            if alias_key:
                env_map.setdefault(alias_key, env_value)
        return env_map

    @staticmethod
    def _yaml_env_map_batch_entries(
        normalized_batch: tuple[int, Sequence[tuple[str, str]]],
    ) -> list[tuple[str, str, str]]:
        _batch_index, batch = normalized_batch
        prepared_entries: list[tuple[str, str, str]] = []
        for env_name, env_value in batch:
            normalized_name = str(env_name or "").strip()
            normalized_value = str(env_value or "").strip()
            if not normalized_name or not normalized_value:
                continue
            alias_key = normalized_name.replace("-", "_")
            prepared_entries.append(
                (
                    normalized_name,
                    normalized_value,
                    "" if alias_key == normalized_name else alias_key,
                )
            )
        return prepared_entries

    @staticmethod
    def _yaml_env_map_family_entries(
        normalized_family: tuple[int, Sequence[tuple[str, str, str]]],
    ) -> list[tuple[str, str, str]]:
        _family_index, family = normalized_family
        return [
            (
                str(env_name),
                str(env_value),
                str(alias_key),
            )
            for env_name, env_value, alias_key in family
        ]

    @staticmethod
    def _yaml_env_map_write_entry(
        write_entry: tuple[int, tuple[str, str, str]],
    ) -> tuple[str, str, str] | None:
        _write_index, entry = write_entry
        if not isinstance(entry, tuple) or len(entry) != 3:
            return None
        env_name, env_value, alias_key = entry
        normalized_name = str(env_name or "").strip()
        normalized_value = str(env_value or "").strip()
        if not normalized_name or not normalized_value:
            return None
        return normalized_name, normalized_value, str(alias_key or "").strip()

    @staticmethod
    def _yaml_env_entry(item: Any) -> list[tuple[str, str]]:
        if isinstance(item, str):
            name, separator, raw_value = item.partition("=")
            env_name = str(name or "").strip().upper()
            env_value = ArtifactQueueProcessor._yaml_decode_secretish_value(raw_value)
            if separator and env_name and env_value:
                return [(env_name, env_value)]
            return []
        if not isinstance(item, dict):
            return []
        env_name = str(item.get("name") or "").strip().upper()
        env_value = item.get("value")
        if env_name and isinstance(env_value, (str, int, float)):
            value = ArtifactQueueProcessor._yaml_decode_secretish_value(env_value)
            if value:
                return [(env_name, value)]
            return []
        for name_key in ("key", "variable"):
            alias_name = str(item.get(name_key) or "").strip().upper()
            alias_value = item.get("value")
            if alias_name and isinstance(alias_value, (str, int, float)):
                value = ArtifactQueueProcessor._yaml_decode_secretish_value(alias_value)
                if value:
                    return [(alias_name, value)]
        if len(item) == 1:
            raw_key, raw_item_value = next(iter(item.items()))
            inline_name = str(raw_key or "").strip().upper()
            inline_value = (
                ArtifactQueueProcessor._yaml_decode_secretish_value(raw_item_value)
                if isinstance(raw_item_value, (str, int, float, bool))
                else ""
            )
            if inline_name and inline_value:
                return [(inline_name, inline_value)]
        return []

    @staticmethod
    def _yaml_env_mapping_entry(item: tuple[Any, Any]) -> list[tuple[str, str]]:
        raw_key, raw_value = item
        env_name = str(raw_key or "").strip().upper()
        if not env_name:
            return []
        if isinstance(raw_value, dict):
            raw_value = raw_value.get("value")
        if not isinstance(raw_value, (str, int, float, bool)):
            return []
        env_value = ArtifactQueueProcessor._yaml_decode_secretish_value(raw_value)
        if not env_value:
            return []
        return [(env_name, env_value)]

    @staticmethod
    def _yaml_env_key_looks_like_variable(value: str) -> bool:
        candidate = str(value or "").strip()
        if not candidate:
            return False
        if re.fullmatch(r"[A-Z][A-Z0-9_\-]{2,}", candidate):
            return True
        return candidate.startswith(("NEXT_PUBLIC_", "VITE_", "REACT_APP_", "NUXT_PUBLIC_", "PUBLIC_"))

    @classmethod
    def _yaml_mapping_looks_like_env_map(cls, mapping: dict[str, Any]) -> bool:
        if not mapping:
            return False
        variable_like_keys = 0
        scalar_values = 0
        for raw_key, raw_value in mapping.items():
            if isinstance(raw_value, (str, int, float, bool)):
                scalar_values += 1
                if cls._yaml_env_key_looks_like_variable(str(raw_key or "")):
                    variable_like_keys += 1
        return scalar_values > 0 and variable_like_keys >= max(1, min(2, scalar_values))

    @staticmethod
    def _yaml_key_fingerprint(value: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())

    @classmethod
    def _yaml_ref_value(cls, mapping: dict[str, Any], *keys: str) -> str:
        for key in keys:
            value = mapping.get(key)
            if value is None:
                value = mapping.get(cls._yaml_key_fingerprint(key))
            if isinstance(value, (str, int, float)):
                candidate = str(value).strip()
                if candidate:
                    return candidate
        return ""

    @staticmethod
    def _yaml_path_hint(path: tuple[str, ...]) -> str:
        return ".".join(str(part or "").strip().lower() for part in path if str(part or "").strip())

    @staticmethod
    def _yaml_has_hint(path_hint: str, *needles: str) -> bool:
        return any(needle in path_hint for needle in needles)

    @staticmethod
    def _yaml_valid_bucket_name(value: str) -> str:
        bucket = str(value or "").strip().lower()
        if re.fullmatch(r"[a-z0-9.\-_]{3,222}", bucket):
            return bucket
        return ""

    @staticmethod
    def _yaml_valid_project_ref(value: str) -> str:
        project_ref = str(value or "").strip().lower()
        if re.fullmatch(r"[a-z0-9\-]{4,64}", project_ref):
            return project_ref
        return ""

    @classmethod
    def _yaml_normalized_mapping(cls, mapping: dict[str, Any]) -> dict[str, Any]:
        raw_mapping = {
            str(key or "").strip().lower(): value
            for key, value in mapping.items()
            if str(key or "").strip()
        }
        normalized = dict(raw_mapping)
        for key, value in list(raw_mapping.items()):
            normalized.setdefault(cls._yaml_key_fingerprint(key), value)
        return normalized

    @classmethod
    def _yaml_child_mapping(cls, mapping: dict[str, Any], *keys: str) -> dict[str, Any]:
        normalized_keys = {cls._yaml_key_fingerprint(key) for key in keys}
        for key, value in mapping.items():
            if cls._yaml_key_fingerprint(str(key or "")) not in normalized_keys:
                continue
            if isinstance(value, dict):
                return value
        return {}

    def _yaml_map_structured_candidates(
        self,
        mapping: dict[str, Any],
        path: tuple[str, ...],
        *,
        source_hint: str = "",
    ) -> list[str]:
        normalized = self._yaml_normalized_mapping(mapping)
        path_hint = self._yaml_path_hint(path)
        candidate_batches = self._run_ordered_local_batch(
            (
                "iac_resource",
                "inline_env",
                "firebase_path",
                "supabase_path",
                "s3_path",
                "gcs_path",
                "spaces_path",
                "azure_path",
                "managed_hosting_path",
                "cloudflare_path",
                "sops_metadata",
                "kubernetes_secret_manifests",
                "ecs_task_definition",
                "lambda_config",
                "aws_app_runner_config",
                "amplify_client_config",
                "gitops_manifests",
                "workflow_manifests",
                "codebuild_buildspec",
                "cloudbuild_config",
                "circleci_config",
                "buildkite_ci",
                "drone_ci",
                "woodpecker_ci",
                "azure_pipelines",
                "bitbucket_pipelines",
                "gitlab_ci",
                "dependabot_config",
                "renovate_config",
                "goreleaser_config",
                "backstage_catalog",
                "docker_auth_map",
                "borg_path",
                "embedded_env_map",
            ),
            lambda family: self._yaml_map_candidate_family(
                family,
                mapping=mapping,
                normalized=normalized,
                path=path,
                path_hint=path_hint,
                source_hint=source_hint,
            ),
            default_factory=list,
        )
        candidate_entry_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._yaml_candidate_batch_entries,
            default_factory=list,
        )
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(candidate_entry_batches)),
            self._yaml_candidate_family_entries,
            default_factory=list,
        )
        prepared_candidate_entries = self._run_ordered_local_batch(
            [
                (candidate_index, candidate)
                for candidate_index, candidate in enumerate(
                    candidate
                    for candidate_family in prepared_candidate_families
                    for candidate in candidate_family
                )
            ],
            self._yaml_candidate_merge_entry,
            default_factory=lambda: None,
        )
        return [candidate for candidate in prepared_candidate_entries if isinstance(candidate, str)]

    def _yaml_map_candidate_family(
        self,
        family: str,
        *,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
        path_hint: str,
        source_hint: str = "",
    ) -> list[str]:
        if family == "iac_resource":
            return self._iac_resource_structured_candidates(mapping, normalized)
        if family == "inline_env":
            env_name = self._yaml_ref_value(normalized, "name").upper()
            env_value = self._yaml_ref_value(normalized, "value")
            if not env_name or not env_value:
                return []
            candidates: list[str] = []
            firebase_env = self._yaml_valid_project_ref(env_value)
            if firebase_env and "FIREBASE" in env_name and any(
                marker in env_name for marker in ("PROJECT", "DATABASE", "RTDB")
            ):
                candidates.append(f"https://{firebase_env}.firebaseio.com")
            supabase_env = self._yaml_valid_project_ref(env_value)
            if supabase_env and "SUPABASE" in env_name and any(
                marker in env_name for marker in ("PROJECT", "REF")
            ):
                candidates.append(f"https://{supabase_env}.supabase.co")
            s3_env = self._yaml_valid_bucket_name(env_value)
            if s3_env and ("S3" in env_name or "AWS" in env_name) and "BUCKET" in env_name:
                candidates.append(f"s3://{s3_env}")
            gcs_env = self._yaml_valid_bucket_name(env_value)
            if gcs_env and any(marker in env_name for marker in ("GCS", "GOOGLE_STORAGE", "GCLOUD")) and "BUCKET" in env_name:
                candidates.append(f"gs://{gcs_env}")
            if "BORG" in env_name and ("REPO" in env_name or "REPOSITORY" in env_name or "LOCATION" in env_name):
                candidates.extend(self._borg_repository_candidates(env_value, normalized))
            return candidates
        if family == "firebase_path":
            if not self._yaml_has_hint(path_hint, "firebase", "rtdb", "realtimedatabase"):
                return []
            project_ref = self._yaml_valid_project_ref(
                self._yaml_ref_value(
                    normalized,
                    "project_id",
                    "projectId",
                    "project-id",
                    "project",
                    "firebase_project_id",
                    "firebaseProjectId",
                    "firebase-project-id",
                    "firebase_project",
                )
            )
            if not project_ref and any(
                key in normalized
                for key in ("name", "database", "database_id", "databaseid", "database-name", "databaseName")
            ):
                project_ref = self._yaml_valid_project_ref(
                    self._yaml_ref_value(normalized, "name", "database", "database_id", "databaseId")
                )
            if project_ref:
                return [f"https://{project_ref}.firebaseio.com"]
            return []
        if family == "supabase_path":
            if not self._yaml_has_hint(path_hint, "supabase"):
                return []
            project_ref = self._yaml_valid_project_ref(
                self._yaml_ref_value(
                    normalized,
                    "project_ref",
                    "projectRef",
                    "project-ref",
                    "ref",
                    "supabase_project_ref",
                    "supabaseProjectRef",
                    "supabase-project-ref",
                    "supabase_ref",
                )
            )
            if not project_ref and "name" in normalized:
                project_ref = self._yaml_valid_project_ref(self._yaml_ref_value(normalized, "name"))
            if project_ref:
                return [f"https://{project_ref}.supabase.co"]
            return []
        if family == "s3_path":
            if not self._yaml_has_hint(path_hint, "aws", "s3"):
                return []
            bucket = self._yaml_valid_bucket_name(
                self._yaml_ref_value(
                    normalized,
                    "bucket",
                    "bucketName",
                    "bucket-name",
                    "bucket_name",
                    "s3_bucket",
                    "s3Bucket",
                    "aws_s3_bucket",
                    "awsS3Bucket",
                    "name",
                )
            )
            if bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
                return [f"s3://{bucket}"]
            return []
        if family == "gcs_path":
            if not self._yaml_has_hint(path_hint, "gcs", "google_storage", "googlecloudstorage"):
                return []
            bucket = self._yaml_valid_bucket_name(
                self._yaml_ref_value(
                    normalized,
                    "bucket",
                    "bucketName",
                    "bucket-name",
                    "bucket_name",
                    "gcs_bucket",
                    "gcsBucket",
                    "google_storage_bucket",
                    "googleStorageBucket",
                    "name",
                )
            )
            if bucket:
                return [f"gs://{bucket}"]
            return []
        if family == "spaces_path":
            if not self._yaml_has_hint(path_hint, "digitalocean", "spaces", "do_spaces"):
                return []
            bucket = self._yaml_valid_bucket_name(
                self._yaml_ref_value(
                    normalized,
                    "bucket",
                    "bucketName",
                    "bucket-name",
                    "bucket_name",
                    "name",
                    "space_name",
                    "spaceName",
                )
            )
            region = str(
                self._yaml_ref_value(
                    normalized,
                    "region",
                    "space_region",
                    "spaceRegion",
                    "bucket_region",
                    "bucketRegion",
                )
            ).strip().lower()
            if bucket and re.fullmatch(r"[a-z0-9\-]{2,32}", region):
                return [f"https://{bucket}.{region}.digitaloceanspaces.com"]
            return []
        if family == "azure_path":
            if not self._yaml_has_hint(path_hint, "azure", "blob"):
                return []
            account_name = str(
                self._yaml_ref_value(
                    normalized,
                    "storage_account_name",
                    "storageAccountName",
                    "storage-account-name",
                    "account_name",
                    "accountName",
                    "account-name",
                    "storage_account",
                    "storageAccount",
                    "storage-account",
                    "azure_storage_account",
                    "azureStorageAccount",
                )
            ).strip().lower()
            container_name = str(
                self._yaml_ref_value(
                    normalized,
                    "name",
                    "container",
                    "container_name",
                    "containerName",
                    "container-name",
                    "blob_container",
                    "blobContainer",
                )
            ).strip().lower()
            if (
                re.fullmatch(r"[a-z0-9\-]{3,24}", account_name)
                and re.fullmatch(r"[^/?#]+", container_name)
            ):
                return [f"https://{account_name}.blob.core.windows.net/{container_name}"]
            return []
        if family == "managed_hosting_path":
            managed_url = _artifact_managed_cloud_url_candidate(
                self._yaml_ref_value(
                    normalized,
                    "url",
                    "uri",
                    "host",
                    "hostname",
                    "domain",
                    "site_url",
                    "siteUrl",
                    "deploy_url",
                    "deployUrl",
                    "deployment_url",
                    "deploymentUrl",
                    "production_url",
                    "productionUrl",
                    "vercel_url",
                    "vercelUrl",
                    "vercel_project_production_url",
                    "vercelProjectProductionUrl",
                    "netlify_url",
                    "netlifyUrl",
                    "netlify_site_url",
                    "netlifySiteUrl",
                    "amplify_url",
                    "amplifyUrl",
                    "amplify_app_url",
                    "amplifyAppUrl",
                    "heroku_url",
                    "herokuUrl",
                    "heroku_app_url",
                    "herokuAppUrl",
                )
            )
            if managed_url:
                return [managed_url]
            return []
        if family == "cloudflare_path":
            return self._yaml_cloudflare_structured_candidates(mapping, normalized, path_hint)
        if family == "sops_metadata":
            return self._yaml_sops_metadata_structured_candidates(mapping, normalized, path_hint)
        if family == "kubernetes_secret_manifests":
            return self._yaml_kubernetes_secret_manifest_structured_candidates(mapping, normalized)
        if family == "ecs_task_definition":
            return ecs_task_definition_candidates(mapping)
        if family == "lambda_config":
            return lambda_config_candidates(mapping)
        if family == "aws_app_runner_config":
            return aws_app_runner_candidates(mapping, source_hint=source_hint)
        if family == "amplify_client_config":
            if not (
                amplify_client_config_artifact_label(source_hint)
                or self._yaml_has_hint(path_hint, "amplify", "cognito", "appsync")
            ):
                return []
            return amplify_client_config_candidates(mapping, source_hint=source_hint)
        if family == "gitops_manifests":
            return self._yaml_gitops_manifest_structured_candidates(mapping, normalized)
        if family == "workflow_manifests":
            return self._yaml_workflow_manifest_structured_candidates(mapping, normalized)
        if family == "codebuild_buildspec":
            return self._yaml_codebuild_buildspec_structured_candidates(mapping, normalized, path)
        if family == "cloudbuild_config":
            return self._yaml_cloudbuild_config_structured_candidates(mapping, normalized, path)
        if family == "circleci_config":
            return self._yaml_circleci_config_structured_candidates(mapping, normalized, path)
        if family == "buildkite_ci":
            return self._yaml_buildkite_ci_structured_candidates(mapping, normalized, path)
        if family == "drone_ci":
            return self._yaml_drone_ci_structured_candidates(mapping, normalized, path)
        if family == "woodpecker_ci":
            return self._yaml_woodpecker_ci_structured_candidates(mapping, normalized, path)
        if family == "azure_pipelines":
            return self._yaml_azure_pipelines_structured_candidates(mapping, normalized, path)
        if family == "bitbucket_pipelines":
            return self._yaml_bitbucket_pipelines_structured_candidates(mapping, normalized, path)
        if family == "gitlab_ci":
            return self._yaml_gitlab_ci_structured_candidates(mapping, normalized, path)
        if family == "dependabot_config":
            return self._yaml_dependabot_config_structured_candidates(mapping, normalized, path_hint)
        if family == "renovate_config":
            return self._yaml_renovate_config_structured_candidates(mapping, normalized, path_hint)
        if family == "goreleaser_config":
            return self._yaml_goreleaser_config_structured_candidates(mapping, normalized, path_hint)
        if family == "backstage_catalog":
            if not (
                backstage_catalog_artifact_label(source_hint)
                or backstage_catalog_mapping_looks_supported(mapping)
            ):
                return []
            return backstage_catalog_candidates(mapping)
        if family == "docker_auth_map":
            if not self._yaml_mapping_looks_like_docker_auth_config(mapping, normalized, path_hint):
                return []
            return self._docker_auth_config_candidates(mapping)
        if family == "borg_path":
            if not self._yaml_has_hint(path_hint, "borg"):
                return []
            repository = self._yaml_ref_value(
                normalized,
                "location",
                "repository",
                "repositoryLocation",
                "repository_location",
                "repo",
                "remote",
                "remoteUrl",
                "remote_url",
                "url",
                "borgRepo",
                "borg_repo",
                "borgRepository",
                "borg_repository",
            )
            return self._borg_repository_candidates(repository, normalized)
        if family == "embedded_env_map":
            if not (
                any(
                    "env" in str(part or "").strip().lower()
                    or "variable" in str(part or "").strip().lower()
                    or str(part or "").strip().lower() in {"data", "stringdata"}
                    for part in path
                )
                or self._yaml_mapping_looks_like_env_map(mapping)
            ):
                return []
            return self._yaml_structured_candidates_from_env_map(self._yaml_env_mapping(mapping))
        return []

    def _yaml_mapping_looks_like_docker_auth_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        if any(key in normalized for key in ("auths", "credhelpers", "credsstore", "credstore")):
            return True
        return self._yaml_has_hint(
            path_hint,
            "docker",
            "dockercfg",
            "dockerconfigjson",
            ".docker",
        )

    def _yaml_workflow_manifest_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> list[str]:
        kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        api_version = self._yaml_ref_value(normalized, "apiVersion", "api_version").lower()
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        if self._yaml_mapping_looks_like_github_actions_workflow(mapping):
            workflow_name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
            _append(f"github-workflow://{workflow_name or 'workflow'}")
            for action_candidate in self._yaml_github_actions_uses_candidates(mapping):
                _append(action_candidate)
            return candidates

        object_identifier = self._yaml_kubernetes_object_identifier(mapping)

        if "tekton.dev" in api_version and kind in {"pipeline", "task", "pipelinerun", "taskrun"}:
            if object_identifier:
                family = {
                    "pipeline": "tekton-pipeline",
                    "task": "tekton-task",
                    "pipelinerun": "tekton-pipelinerun",
                    "taskrun": "tekton-taskrun",
                }[kind]
                _append(f"{family}://{object_identifier}")
            for repo_candidate in self._yaml_gitops_repository_candidates_from_mapping(mapping):
                _append(repo_candidate)
            return candidates

        if "argoproj.io" in api_version and kind in {
            "workflow",
            "workflowtemplate",
            "cronworkflow",
            "clusterworkflowtemplate",
        }:
            if object_identifier:
                family = {
                    "workflow": "argo-workflow",
                    "workflowtemplate": "argo-workflowtemplate",
                    "cronworkflow": "argo-cronworkflow",
                    "clusterworkflowtemplate": "argo-clusterworkflowtemplate",
                }[kind]
                _append(f"{family}://{object_identifier}")
            for repo_candidate in self._yaml_gitops_repository_candidates_from_mapping(mapping):
                _append(repo_candidate)
            return candidates

        return candidates

    def _yaml_mapping_looks_like_github_actions_workflow(self, mapping: dict[str, Any]) -> bool:
        normalized = self._yaml_normalized_mapping(mapping)
        jobs = normalized.get("jobs")
        if not isinstance(jobs, dict):
            return False
        return bool(self._yaml_github_actions_uses_candidates(mapping) or self._yaml_github_actions_has_runs_on(jobs))

    def _yaml_github_actions_has_runs_on(self, value: Any) -> bool:
        if isinstance(value, dict):
            for key, child in value.items():
                if self._yaml_key_fingerprint(str(key or "")) == "runson":
                    return True
                if self._yaml_github_actions_has_runs_on(child):
                    return True
        elif isinstance(value, list):
            return any(self._yaml_github_actions_has_runs_on(item) for item in value)
        return False

    def _yaml_worker_walk_values(
        self,
        value: Any,
        state: Any,
        worker: Callable[[tuple[Any, Any, Any]], list[Any]],
        *,
        use_workers: bool,
        list_limit: int | None = None,
    ) -> list[Any]:
        if isinstance(value, dict):
            child_jobs = [(raw_key, child, state) for raw_key, child in value.items()]
        elif isinstance(value, list):
            items = value if list_limit is None else value[:list_limit]
            child_jobs = [(None, item, state) for item in items]
        else:
            return []
        child_batches = (
            self._run_ordered_local_batch(
                child_jobs,
                worker,
                default_factory=list,
            )
            if use_workers
            else [worker(child_job) for child_job in child_jobs]
        )
        return [
            candidate
            for child_values in child_batches
            for candidate in child_values
        ]

    def _yaml_github_actions_uses_candidates(
        self,
        value: Any,
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(candidate: str) -> None:
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        for candidate in self._yaml_github_actions_uses_candidate_values(
            value,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_github_actions_uses_candidate_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_github_actions_uses_child_candidate_values,
            use_workers=use_workers,
        )

    def _yaml_github_actions_uses_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, _state = child_job
        values: list[str] = []
        if raw_key is not None and self._yaml_key_fingerprint(str(raw_key or "")) == "uses":
            values.extend(self._yaml_github_actions_uses_candidate(child))
        values.extend(
            self._yaml_github_actions_uses_candidate_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_github_actions_uses_candidate(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'")
        if not raw_value or raw_value.startswith(("./", "../")):
            return []
        if raw_value.startswith(("docker://", "oci://")):
            candidate = _artifact_container_image_url_candidate(raw_value)
            return [candidate] if candidate else []
        if raw_value.startswith(("http://", "https://")):
            repository_value = raw_value.split("@", 1)[0]
            normalized = _normalize_artifact_text_url(repository_value)
            return [self._strip_git_repository_suffix(normalized)] if normalized else []

        ref_value = raw_value.split("@", 1)[0].strip("/")
        parts = ref_value.split("/")
        if len(parts) < 2:
            return []
        owner, repository = parts[0], parts[1]
        if not (
            re.fullmatch(r"[A-Za-z0-9_.-]+", owner)
            and re.fullmatch(r"[A-Za-z0-9_.-]+", repository)
        ):
            return []
        encoded_ref = quote(ref_value, safe="/._:@+=-")
        return [
            f"https://github.com/{owner}/{repository}",
            f"github-action://{encoded_ref}",
        ]

    def _yaml_codebuild_buildspec_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_codebuild_buildspec(mapping, normalized):
            return []

        env_mapping = self._yaml_child_mapping(mapping, "env")
        if not env_mapping:
            return []

        secret_jobs: list[tuple[str, Any]] = []
        parameter_store = self._yaml_child_mapping(env_mapping, "parameter-store", "parameter_store", "parameterstore")
        for parameter_ref in parameter_store.values() if parameter_store else ():
            secret_jobs.append(("parameter_store", parameter_ref))

        secrets_manager = self._yaml_child_mapping(env_mapping, "secrets-manager", "secrets_manager", "secretsmanager")
        for secret_ref in secrets_manager.values() if secrets_manager else ():
            secret_jobs.append(("secrets_manager", secret_ref))

        candidate_entries = self._run_ordered_local_batch(
            secret_jobs,
            self._yaml_codebuild_secret_job_candidate,
            default_factory=str,
        )
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        for candidate in candidate_entries:
            _append(candidate)
        return candidates

    def _yaml_codebuild_secret_job_candidate(self, secret_job: tuple[str, Any]) -> str:
        family, raw_ref = secret_job
        if family == "parameter_store":
            parameter_segment = self._yaml_external_secret_ref_segment(raw_ref)
            return f"aws-parameterstore://{parameter_segment}" if parameter_segment else ""
        if family == "secrets_manager":
            secret_segment = self._yaml_codebuild_secret_ref_segment(raw_ref)
            return f"aws-secretsmanager://{secret_segment}" if secret_segment else ""
        return ""

    def _yaml_mapping_looks_like_codebuild_buildspec(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if "version" not in normalized:
            return False
        has_buildspec_shape = any(isinstance(normalized.get(key), dict) for key in ("phases", "env", "artifacts", "cache"))
        if not has_buildspec_shape:
            return False
        env_mapping = self._yaml_child_mapping(mapping, "env")
        if not env_mapping:
            return bool(isinstance(normalized.get("phases"), dict))
        return bool(
            self._yaml_child_mapping(env_mapping, "parameter-store", "parameter_store", "parameterstore")
            or self._yaml_child_mapping(env_mapping, "secrets-manager", "secrets_manager", "secretsmanager")
            or isinstance(normalized.get("phases"), dict)
        )

    def _yaml_codebuild_secret_ref_segment(self, value: Any) -> str:
        raw_value = str(value or "").strip().strip("\"'")
        if not raw_value:
            return ""
        if raw_value.lower().startswith("arn:"):
            arn_match = re.match(
                r"^(arn:aws[a-z-]*:secretsmanager:[^:\s]+:\d{12}:secret:[^:\s]+)",
                raw_value,
                re.IGNORECASE,
            )
            return self._yaml_external_secret_ref_segment(arn_match.group(1) if arn_match else raw_value)
        return self._yaml_external_secret_ref_segment(raw_value.split(":", 1)[0])

    def _yaml_cloudbuild_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_cloudbuild_config(mapping, normalized):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        for image_candidate in self._yaml_cloudbuild_image_candidates(mapping):
            _append(image_candidate)

        logs_bucket = self._yaml_ref_value(normalized, "logsBucket", "logs_bucket")
        if logs_bucket.lower().startswith("gs://"):
            _append(logs_bucket)

        return candidates

    def _yaml_mapping_looks_like_cloudbuild_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if any(key in normalized for key in ("steps", "images", "substitutions", "logsbucket")):
            logs_bucket = self._yaml_ref_value(normalized, "logsBucket", "logs_bucket")
            return bool(
                self._yaml_cloudbuild_image_candidates(mapping)
                or logs_bucket.lower().startswith("gs://")
            )
        return False

    def _yaml_cloudbuild_image_candidates(self, mapping: dict[str, Any]) -> list[str]:
        image_jobs: list[tuple[Any, str]] = []
        for step_entry in self._yaml_ref_collection(mapping, "steps"):
            if isinstance(step_entry, dict):
                image_jobs.append((step_entry, "name"))
            else:
                image_jobs.append((step_entry, ""))

        for image_entry in self._yaml_ref_collection(mapping, "images"):
            image_jobs.append((image_entry, ""))

        artifacts = self._yaml_child_mapping(mapping, "artifacts")
        if artifacts:
            for image_entry in self._yaml_ref_collection(artifacts, "images"):
                image_jobs.append((image_entry, ""))

        return self._yaml_ci_image_candidates_from_jobs(image_jobs)

    def _yaml_ci_image_candidates_from_jobs(
        self,
        image_jobs: Sequence[tuple[Any, str]],
    ) -> list[str]:
        candidate_values = self._run_ordered_local_batch(
            list(image_jobs),
            self._yaml_ci_image_job_candidate,
            default_factory=str,
        )
        candidates: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_values:
            if not candidate or candidate.lower() in seen:
                continue
            seen.add(candidate.lower())
            candidates.append(candidate)
        return candidates

    def _yaml_ci_image_job_candidate(self, image_job: tuple[Any, str]) -> str:
        entry, image_key = image_job
        raw_value = entry
        if image_key and isinstance(entry, dict):
            raw_value = self._yaml_ref_value(self._yaml_normalized_mapping(entry), image_key)
        return _artifact_container_image_url_candidate(
            str(raw_value or "").strip().strip("\"'"),
            require_explicit_registry=True,
        )

