    def _yaml_mapping_looks_like_circleci_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if "version" not in normalized:
            return False
        if any(key in normalized for key in ("jobs", "workflows", "orbs", "executors", "commands")):
            return True
        return bool(self._yaml_circleci_container_candidates(mapping))

    def _yaml_circleci_workflow_names(self, mapping: dict[str, Any]) -> list[str]:
        workflows = self._yaml_child_mapping(mapping, "workflows")
        if not workflows:
            return []
        names: list[str] = []
        seen: set[str] = set()
        for raw_name, raw_value in workflows.items():
            name = str(raw_name or "").strip()
            if not name or self._yaml_key_fingerprint(name) == "version":
                continue
            if not isinstance(raw_value, (dict, list, str)):
                continue
            identifier = self._yaml_external_secret_ref_segment(name)
            if not identifier or identifier.lower() in seen:
                continue
            seen.add(identifier.lower())
            names.append(identifier)
        return names

    def _yaml_circleci_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(candidate: str) -> None:
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_circleci_container_candidate_values(
            mapping,
            (),
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_circleci_container_candidate_values(
        self,
        value: Any,
        path_parts: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            path_parts,
            self._yaml_circleci_container_child_candidate_values,
            use_workers=use_workers,
            list_limit=256,
        )

    def _yaml_circleci_container_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, path_parts = child_job
        if raw_key is None:
            return self._yaml_circleci_container_candidate_values(
                child,
                path_parts,
                use_workers=False,
            )
        key_name = self._yaml_key_fingerprint(str(raw_key or ""))
        child_path = (*path_parts, key_name)
        values: list[str] = []
        if key_name == "image" and (
            "docker" in path_parts
            or "executors" in path_parts
            or "jobs" in path_parts
        ):
            candidate = _artifact_container_image_url_candidate(
                str(child or "").strip().strip("\"'"),
                require_explicit_registry=True,
            )
            if candidate:
                values.append(candidate)
        values.extend(
            self._yaml_circleci_container_candidate_values(
                child,
                child_path,
                use_workers=False,
            )
        )
        return values

    def _yaml_buildkite_ci_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_buildkite_ci(mapping, normalized):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        pipeline_name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
        _append(f"buildkite-pipeline://{pipeline_name or 'pipeline'}")
        for image_candidate in self._yaml_buildkite_plugin_image_candidates(mapping):
            _append(image_candidate)
        return candidates

    def _yaml_mapping_looks_like_buildkite_ci(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        steps = normalized.get("steps")
        if not isinstance(steps, list):
            return False
        for step_entry in steps[:64]:
            if not isinstance(step_entry, dict):
                continue
            step_normalized = self._yaml_normalized_mapping(step_entry)
            if any(key in step_normalized for key in ("label", "command", "commands", "plugins", "block", "wait")):
                return True
        return False

    def _yaml_buildkite_plugin_image_candidates(self, mapping: dict[str, Any]) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        plugin_jobs: list[tuple[int, Any]] = []
        for step_index, step_entry in enumerate(self._yaml_ref_collection(mapping, "steps")):
            if not isinstance(step_entry, dict):
                continue
            step_normalized = self._yaml_normalized_mapping(step_entry)
            plugins = step_normalized.get("plugins")
            if plugins is not None:
                plugin_jobs.append((step_index, plugins))

        plugin_batches = self._run_ordered_local_batch(
            plugin_jobs,
            self._yaml_buildkite_plugin_image_candidate_values,
            default_factory=list,
        )
        for plugin_batch in plugin_batches:
            for candidate in plugin_batch:
                if not candidate or candidate.lower() in seen:
                    continue
                seen.add(candidate.lower())
                candidates.append(candidate)
        return candidates

    def _yaml_buildkite_plugin_image_candidate_values(
        self,
        plugin_job: tuple[int, Any],
    ) -> list[str]:
        _step_index, plugins = plugin_job
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            candidate = _artifact_container_image_url_candidate(
                str(value or "").strip().strip("\"'"),
                require_explicit_registry=True,
            )
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        def _walk_plugins(value: Any) -> None:
            if isinstance(value, dict):
                normalized = self._yaml_normalized_mapping(value)
                _append(self._yaml_ref_value(normalized, "image", "container", "docker_image", "dockerImage"))
                for child in value.values():
                    if isinstance(child, (dict, list)):
                        _walk_plugins(child)
            elif isinstance(value, list):
                for item in value[:128]:
                    _walk_plugins(item)

        _walk_plugins(plugins)
        return candidates

