    def _yaml_ci_resource_family_candidates(
        self,
        family_job: tuple[str, str, dict[str, Any]],
    ) -> list[str]:
        platform, family, mapping = family_job
        if platform == "circleci":
            if family == "workflows":
                return [
                    f"circleci-pipeline://{workflow_name}"
                    for workflow_name in self._yaml_circleci_workflow_names(mapping)
                ]
            if family == "containers":
                return self._yaml_circleci_container_candidates(mapping)
        if platform == "azure_pipelines":
            if family == "repositories":
                return self._yaml_azure_pipelines_repository_candidates(mapping)
            if family == "containers":
                return self._yaml_azure_pipelines_container_candidates(mapping)
        if platform == "bitbucket_pipelines":
            if family == "repositories":
                return self._yaml_bitbucket_pipelines_repository_candidates(mapping)
            if family == "containers":
                return self._yaml_bitbucket_pipelines_container_candidates(mapping)
        if platform == "gitlab_ci":
            if family == "includes":
                return self._yaml_gitlab_ci_include_repository_candidates(mapping)
            if family == "services":
                return self._yaml_gitlab_ci_service_container_candidates(mapping)
        return []

    def _yaml_mapping_looks_like_azure_pipelines(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if any(key in normalized for key in ("trigger", "pr", "schedules", "stages", "jobs", "steps", "pool")):
            return True
        resources = self._yaml_child_mapping(mapping, "resources")
        if not resources:
            return False
        resource_normalized = self._yaml_normalized_mapping(resources)
        return any(key in resource_normalized for key in ("repositories", "containers", "pipelines", "builds"))

    def _yaml_azure_pipelines_repository_candidates(self, mapping: dict[str, Any]) -> list[str]:
        resources = self._yaml_child_mapping(mapping, "resources")
        if not resources:
            return []
        repositories = self._yaml_ref_collection(resources, "repositories")
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        repository_batches = self._run_ordered_local_batch(
            repositories,
            self._yaml_azure_pipeline_repository_entry_candidates,
            default_factory=list,
        )
        for repository_values in repository_batches:
            for candidate in repository_values:
                _append(candidate)
        return candidates

    def _yaml_azure_pipeline_repository_entry_candidates(self, value: Any) -> list[str]:
        if isinstance(value, str):
            return self._yaml_gitops_repository_candidates(value)
        if not isinstance(value, dict):
            return []
        normalized = self._yaml_normalized_mapping(value)
        explicit_url = self._yaml_ref_value(normalized, "url", "endpointUrl", "endpoint_url", "repositoryUrl")
        if explicit_url:
            return self._yaml_gitops_repository_candidates(explicit_url)

        repo_type = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "type"))
        repo_name = str(self._yaml_ref_value(normalized, "name")).strip().strip("\"'")
        if not repo_name or repo_name.lower() == "self" or any(marker in repo_name for marker in ("${", "$(", "{{", "}}")):
            return []

        repo_path = repo_name.strip("/")
        if len(repo_path.split("/")) < 2:
            return []
        if not re.fullmatch(r"[A-Za-z0-9_.@/-]+", repo_path):
            return []

        if repo_type == "github":
            return [f"https://github.com/{repo_path}"]
        if repo_type in {"bitbucket", "bitbucketcloud"}:
            return [f"https://bitbucket.org/{repo_path}"]
        if repo_type == "gitlab":
            return [f"https://gitlab.com/{repo_path}"]
        return []

    @classmethod
    def _yaml_ref_collection(cls, mapping: dict[str, Any], *keys: str) -> list[Any]:
        normalized = cls._yaml_normalized_mapping(mapping)
        for key in keys:
            value = normalized.get(key) or normalized.get(cls._yaml_key_fingerprint(key))
            if isinstance(value, list):
                return value
            if isinstance(value, dict):
                return list(value.values())
        return []

    def _yaml_azure_pipelines_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = _artifact_container_image_url_candidate(value, require_explicit_registry=True)
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        resources = self._yaml_child_mapping(mapping, "resources")
        if resources:
            container_batches = self._run_ordered_local_batch(
                self._yaml_ref_collection(resources, "containers"),
                self._yaml_azure_pipeline_container_resource_entry_candidates,
                default_factory=list,
            )
            for container_values in container_batches:
                for container_value in container_values:
                    _append(container_value)

        for candidate in self._yaml_azure_pipelines_container_walk_values(
            mapping,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_azure_pipeline_container_resource_entry_candidates(
        self,
        value: Any,
    ) -> list[str]:
        if not isinstance(value, dict):
            return [str(value or "")]
        normalized_container = self._yaml_normalized_mapping(value)
        return [self._yaml_ref_value(normalized_container, "image", "container")]

    def _yaml_azure_pipelines_container_walk_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_azure_pipelines_container_child_values,
            use_workers=use_workers,
        )

    def _yaml_azure_pipelines_container_child_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, _state = child_job
        if raw_key is None:
            return self._yaml_azure_pipelines_container_walk_values(
                child,
                use_workers=False,
            )
        values: list[str] = []
        if self._yaml_key_fingerprint(str(raw_key or "")) == "container" and isinstance(child, str):
            values.append(child)
        values.extend(
            self._yaml_azure_pipelines_container_walk_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_bitbucket_pipelines_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_bitbucket_pipelines(mapping, normalized):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        pipeline_name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
        _append(f"bitbucket-pipeline://{pipeline_name or 'pipeline'}")

        resource_batches = self._run_ordered_local_batch(
            (
                ("bitbucket_pipelines", "repositories", mapping),
                ("bitbucket_pipelines", "containers", mapping),
            ),
            self._yaml_ci_resource_family_candidates,
            default_factory=list,
        )
        for resource_values in resource_batches:
            for resource_candidate in resource_values:
                _append(resource_candidate)
        return candidates

    def _yaml_mapping_looks_like_bitbucket_pipelines(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        pipelines = normalized.get("pipelines")
        if not isinstance(pipelines, dict):
            return False
        if any(key in normalized for key in ("definitions", "image", "clone", "options")):
            return True
        return any(
            self._yaml_key_fingerprint(str(key or "")) in {"default", "branches", "tags", "pullrequests", "custom"}
            for key in pipelines
        )

    def _yaml_bitbucket_pipelines_repository_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_bitbucket_repository_candidate_values(
            mapping,
            (),
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_bitbucket_repository_value_candidates(
        self,
        value: Any,
        *,
        allow_owner_repo: bool,
    ) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'").strip("/")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        candidates_for_value = self._yaml_gitops_repository_candidates(raw_value)
        if candidates_for_value:
            return candidates_for_value
        if not allow_owner_repo:
            return []
        parts = [part for part in raw_value.split("/") if part]
        if len(parts) < 2:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts[:2]):
            return []
        return [f"https://bitbucket.org/{parts[0]}/{parts[1]}"]

    def _yaml_bitbucket_repository_candidate_values(
        self,
        value: Any,
        path_parts: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            path_parts,
            self._yaml_bitbucket_repository_child_candidate_values,
            use_workers=use_workers,
            list_limit=256,
        )

    def _yaml_bitbucket_repository_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, path_parts = child_job
        if raw_key is None:
            return self._yaml_bitbucket_repository_candidate_values(
                child,
                path_parts,
                use_workers=False,
            )
        repo_key_names = {
            "giturl",
            "cloneurl",
            "repourl",
            "repositoryurl",
            "repository",
            "repositories",
            "repo",
        }
        key_name = self._yaml_key_fingerprint(str(raw_key or ""))
        child_path = (*path_parts, key_name)
        in_repository_context = any(
            part in {"repository", "repositories", "repo"}
            for part in path_parts
        )
        values: list[str] = []
        if isinstance(child, str) and (key_name in repo_key_names or in_repository_context):
            values.extend(
                self._yaml_bitbucket_repository_value_candidates(
                    child,
                    allow_owner_repo=key_name in repo_key_names or in_repository_context,
                )
            )
        values.extend(
            self._yaml_bitbucket_repository_candidate_values(
                child,
                child_path,
                use_workers=False,
            )
        )
        return values

    def _yaml_bitbucket_pipelines_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(candidate: str) -> None:
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_bitbucket_container_candidate_values(
            mapping,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_bitbucket_container_candidate_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_bitbucket_container_child_candidate_values,
            use_workers=use_workers,
            list_limit=256,
        )

    def _yaml_bitbucket_container_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, _state = child_job
        if raw_key is None:
            return self._yaml_bitbucket_container_candidate_values(
                child,
                use_workers=False,
            )
        values: list[str] = []
        key_name = self._yaml_key_fingerprint(str(raw_key or ""))
        if key_name in {"image", "container"}:
            if isinstance(child, dict):
                normalized_child = self._yaml_normalized_mapping(child)
                raw_value = self._yaml_ref_value(normalized_child, "name", "image", "container")
            else:
                raw_value = str(child or "").strip().strip("\"'")
            candidate = _artifact_container_image_url_candidate(
                raw_value,
                require_explicit_registry=True,
            )
            if candidate:
                values.append(candidate)
        values.extend(
            self._yaml_bitbucket_container_candidate_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_gitlab_ci_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_gitlab_ci(mapping, normalized):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        workflow = self._yaml_child_mapping(mapping, "workflow")
        if workflow:
            workflow_name = self._yaml_external_secret_ref_segment(
                self._yaml_ref_value(self._yaml_normalized_mapping(workflow), "name")
            )
            if workflow_name:
                _append(f"gitlab-pipeline://{workflow_name}")

        resource_batches = self._run_ordered_local_batch(
            (
                ("gitlab_ci", "includes", mapping),
                ("gitlab_ci", "services", mapping),
            ),
            self._yaml_ci_resource_family_candidates,
            default_factory=list,
        )
        for resource_values in resource_batches:
            for resource_candidate in resource_values:
                _append(resource_candidate)
        return candidates

    def _yaml_mapping_looks_like_gitlab_ci(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if any(key in normalized for key in ("include", "stages", "workflow", "before_script", "after_script")):
            return True
        for key, value in mapping.items():
            key_name = str(key or "").strip()
            if not key_name or key_name.startswith(".") or key_name in {"default", "variables", "cache"}:
                continue
            if not isinstance(value, dict):
                continue
            job_normalized = self._yaml_normalized_mapping(value)
            if any(job_key in job_normalized for job_key in ("script", "stage", "extends", "rules", "needs")):
                return True
        return False

    def _yaml_gitlab_ci_include_repository_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        normalized = self._yaml_normalized_mapping(mapping)
        include_value = normalized.get("include")
        if include_value is not None:
            for candidate in self._yaml_gitlab_ci_include_candidate_values(
                include_value,
                use_workers=use_workers,
            ):
                _append(candidate)
        return candidates

    def _yaml_gitlab_ci_include_candidate_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        if isinstance(value, dict):
            direct_values: list[str] = []
            normalized = self._yaml_normalized_mapping(value)
            remote_value = self._yaml_ref_value(normalized, "remote")
            if remote_value:
                direct_values.extend(self._yaml_gitops_repository_candidates(remote_value))
            direct_values.extend(
                self._yaml_gitlab_ci_project_repository_candidates(
                    self._yaml_ref_value(normalized, "project")
                )
            )
            direct_values.extend(
                self._yaml_gitlab_ci_component_candidates(
                    self._yaml_ref_value(normalized, "component")
                )
            )
            child_jobs = [
                child
                for child in value.values()
                if isinstance(child, (dict, list))
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._yaml_gitlab_ci_include_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitlab_ci_include_candidate_values(
                        child,
                        use_workers=False,
                    )
                    for child in child_jobs
                ]
            )
            return [
                *direct_values,
                *[
                    candidate
                    for child_values in child_batches
                    for candidate in child_values
                ],
            ]
        if isinstance(value, list):
            item_jobs = list(value)
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._yaml_gitlab_ci_include_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitlab_ci_include_candidate_values(
                        item,
                        use_workers=False,
                    )
                    for item in item_jobs
                ]
            )
            return [
                candidate
                for item_values in item_batches
                for candidate in item_values
            ]
        return []

    def _yaml_gitlab_ci_include_child_candidate_values(
        self,
        child: Any,
    ) -> list[str]:
        return self._yaml_gitlab_ci_include_candidate_values(
            child,
            use_workers=False,
        )

    def _yaml_gitlab_ci_project_repository_candidates(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'").strip("/")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        if raw_value.startswith(("http://", "https://", "git@", "ssh://", "git://")):
            return self._yaml_gitops_repository_candidates(raw_value)
        parts = [part for part in raw_value.split("/") if part]
        if len(parts) < 2:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts):
            return []
        if "." in parts[0]:
            return [f"https://{parts[0].lower()}/{'/'.join(parts[1:])}"]
        return [f"https://gitlab.com/{'/'.join(parts)}"]

    def _yaml_gitlab_ci_component_candidates(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        component_ref = raw_value.split("@", 1)[0].strip("/")
        parts = [part for part in component_ref.split("/") if part]
        if len(parts) < 3 or "." not in parts[0]:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts[:3]):
            return []
        return [f"https://{parts[0].lower()}/{parts[1]}/{parts[2]}"]

    def _yaml_gitlab_ci_service_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            raw_value = str(value or "").strip().strip("\"'")
            if not raw_value:
                return
            candidate = _artifact_container_image_url_candidate(raw_value, require_explicit_registry=True)
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_gitlab_ci_service_container_values(
            mapping,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_gitlab_ci_service_container_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[Any]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_gitlab_ci_service_container_child_values,
            use_workers=use_workers,
        )

    def _yaml_gitlab_ci_service_container_child_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[Any]:
        raw_key, child, _state = child_job
        if raw_key is None:
            return self._yaml_gitlab_ci_service_container_values(
                child,
                use_workers=False,
            )
        values: list[Any] = []
        if self._yaml_key_fingerprint(str(raw_key or "")) == "services":
            self._yaml_gitlab_ci_collect_service_images(child, values.append)
        values.extend(
            self._yaml_gitlab_ci_service_container_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_gitlab_ci_collect_service_images(
        self,
        value: Any,
        append: Callable[[Any], None],
    ) -> None:
        if isinstance(value, str):
            append(value)
            return
        if isinstance(value, list):
            for item in value:
                self._yaml_gitlab_ci_collect_service_images(item, append)
            return
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            service_name = self._yaml_ref_value(normalized, "name", "image")
            if service_name:
                append(service_name)

    def _yaml_dependabot_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        if not self._yaml_mapping_looks_like_dependabot_config(mapping, normalized, path_hint):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            candidate = _artifact_package_registry_host_or_url_candidate(str(value or ""))
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for key in (
            "url",
            "registry",
            "registryUrl",
            "registry_url",
            "registryHost",
            "registry_host",
            "host",
            "hostName",
            "hostname",
            "host_name",
            "indexUrl",
            "index_url",
            "source",
        ):
            raw_value = self._yaml_ref_value(normalized, key)
            if raw_value:
                _append(raw_value)
        return candidates

    def _yaml_mapping_looks_like_dependabot_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        if any(key in normalized for key in ("updates", "registries")) and "version" in normalized:
            return True
        registry_type = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "type"))
        if registry_type in {
            "dockerregistry",
            "gitregistry",
            "hexorganization",
            "mavenrepository",
            "npmregistry",
            "nugetfeed",
            "pythonindex",
            "rubygemsserver",
            "terraformregistry",
        }:
            return True
        return "registries" in path_hint and any(
            key in normalized
            for key in (
                "url",
                "registry",
                "registryurl",
                "registryhost",
                "host",
                "hostname",
                "host_name",
                "indexurl",
                "source",
            )
        )

    def _yaml_renovate_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        if not self._yaml_mapping_looks_like_renovate_config(mapping, normalized, path_hint):
            return []

        raw_candidates: list[Any] = []
        candidates: list[str] = []
        seen: set[str] = set()

        def _append_candidate(candidate: str) -> None:
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for key in (
            "matchHost",
            "match_host",
            "host",
            "hostname",
            "hostName",
            "registryUrl",
            "registry_url",
            "endpoint",
            "npmRegistryServer",
            "npm_registry_server",
        ):
            raw_value = self._yaml_ref_value(normalized, key)
            if raw_value:
                raw_candidates.append(raw_value)

        for key in ("registryUrls", "registry_urls"):
            value = normalized.get(key) or normalized.get(self._yaml_key_fingerprint(key))
            if isinstance(value, list):
                for item in value[:64]:
                    if isinstance(item, (str, int, float)):
                        raw_candidates.append(item)
            elif isinstance(value, (str, int, float)):
                raw_candidates.append(value)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._renovate_text_candidate_entry,
            default_factory=str,
        )
        for candidate in candidate_entries:
            _append_candidate(candidate)
        return candidates

    def _yaml_mapping_looks_like_renovate_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        if any(key in normalized for key in ("hostrules", "packagerules", "renovate")):
            return True
        if any(part in path_hint for part in ("hostrules", "packagerules", "renovate")):
            return any(
                key in normalized
                for key in (
                    "matchhost",
                    "host",
                    "hostname",
                    "registryurl",
                    "registryurls",
                    "endpoint",
                    "npmregistryserver",
                )
            )
        if "hosttype" in normalized and any(
            key in normalized
            for key in ("matchhost", "registryurl", "endpoint", "host", "hostname")
        ):
            return True
        return False

    def _renovate_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        source_name = Path(str(source_hint or "").replace("\\", "/")).name.lower()
        if not (
            _renovate_config_artifact_label(source_hint)
            or source_name in {".renovaterc", "renovaterc"}
        ):
            return ""

        raw_candidates: list[str] = []
        in_registry_array = False
        key_pattern = re.compile(
            r"""
            ^["']?
            (?P<key>
                matchHost|match_host|registryUrl|registry_url|registryUrls|
                registry_urls|endpoint|npmRegistryServer|npm_registry_server|
                host|hostname|hostName|host_name
            )
            ["']?\s*[:=]\s*(?P<value>.+?)\s*,?\s*$
            """,
            re.IGNORECASE | re.VERBOSE,
        )

        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line or line.startswith(("//", "#")):
                continue

            candidate_values: list[str] = []
            key_match = key_pattern.match(line)
            if key_match:
                key = self._yaml_key_fingerprint(key_match.group("key"))
                value = key_match.group("value").strip()
                if key == "registryurls" and "[" in value and "]" not in value:
                    in_registry_array = True
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", value))
                if not candidate_values and not value.startswith(("[", "{")):
                    candidate_values.append(value.rstrip(","))
            elif in_registry_array:
                if "]" in line:
                    in_registry_array = False
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", line))

            raw_candidates.extend(candidate_values)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._renovate_text_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)

        return "\n".join(lines)

    @staticmethod
    def _renovate_text_candidate_entry(raw_value: Any) -> str:
        value = ArtifactQueueProcessor._parse_key_value_scalar(str(raw_value or "").strip())
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _security_scanner_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not _security_scanner_config_artifact_label(source_hint):
            return ""

        allowed_keys = {
            "apiurl",
            "baseurl",
            "bcapiurl",
            "dbrepository",
            "downloadurl",
            "endpoint",
            "godatabaserepository",
            "host",
            "hostname",
            "hosturl",
            "javadatabaserepository",
            "pythondatabaserepository",
            "registry",
            "registryurl",
            "repositories",
            "repos",
            "repo",
            "repository",
            "server",
            "serverurl",
            "sonarhosturl",
            "sonarlinkscis",
            "sonarlinksci",
            "sonarlinkshomepage",
            "sonarlinksissue",
            "sonarlinks scm",
            "source",
            "tokenendpoint",
            "url",
            "urls",
            "weburl",
        }
        allowed_keys = {self._yaml_key_fingerprint(key) for key in allowed_keys}
        list_keys = {
            "dbrepository",
            "repositories",
            "repository",
            "repos",
            "repo",
            "urls",
        }

        raw_candidates: list[str] = []
        in_value_array = False

        def _append_raw_candidate(raw_value: str) -> None:
            if len(raw_candidates) >= 4096:
                return
            value = str(raw_value or "").strip()
            if not value:
                return
            raw_candidates.append(value)

        document = _safe_json_loads(str(text or "").strip())
        if isinstance(document, (dict, list)):
            for candidate in self._security_scanner_structured_document_values(
                document,
                allowed_keys,
                use_workers=True,
            ):
                _append_raw_candidate(candidate)

        assignment_pattern = re.compile(
            r"""
            ^\s*-?\s*
            ["']?(?P<key>[A-Za-z0-9_.-]+)["']?
            \s*[:=]\s*
            (?P<value>.+?)\s*,?\s*$
            """,
            re.VERBOSE,
        )

        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line or line.startswith(("#", "//", "/*", "*")):
                continue

            candidate_values: list[str] = []
            match = assignment_pattern.match(line)
            if match:
                key = self._yaml_key_fingerprint(str(match.group("key") or ""))
                if key not in allowed_keys:
                    in_value_array = False
                    continue
                value = str(match.group("value") or "").strip()
                if key in list_keys and "[" in value and "]" not in value:
                    in_value_array = True
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", value))
                if not candidate_values and not value.startswith(("[", "{", "!", "&", "*")):
                    candidate_values.append(value.rstrip(","))
            elif in_value_array:
                if "]" in line:
                    in_value_array = False
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", line))
                if not candidate_values:
                    bare_value = line.rstrip(",").strip()
                    if bare_value and not bare_value.startswith(("]", "{", "#", "//")):
                        candidate_values.append(bare_value)

            for candidate_value in candidate_values:
                _append_raw_candidate(candidate_value)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._security_scanner_config_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)

        return "\n".join(lines)

    def _security_scanner_structured_document_values(
        self,
        value: Any,
        allowed_keys: set[str],
        *,
        use_workers: bool,
    ) -> list[str]:
        if isinstance(value, dict):
            child_jobs = [
                (child_index, raw_key, child, allowed_keys)
                for child_index, (raw_key, child) in enumerate(list(value.items())[:4096])
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._security_scanner_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._security_scanner_structured_document_child_values_for_entry(
                        raw_key,
                        child,
                        allowed_keys,
                    )
                    for _child_index, raw_key, child, allowed_keys in child_jobs
                ]
            )
            return [
                candidate
                for child_values in child_batches
                for candidate in child_values
            ][:4096]
        if isinstance(value, list):
            item_jobs = [
                (item_index, None, item, allowed_keys)
                for item_index, item in enumerate(value[:4096])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._security_scanner_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._security_scanner_structured_document_values(
                        item,
                        allowed_keys,
                        use_workers=False,
                    )
                    for _item_index, _raw_key, item, allowed_keys in item_jobs
                ]
            )
            return [
                candidate
                for item_values in item_batches
                for candidate in item_values
            ][:4096]
        return []

    def _security_scanner_structured_document_child_values(
        self,
        child_job: tuple[int, Any, Any, set[str]],
    ) -> list[str]:
        _child_index, raw_key, child, allowed_keys = child_job
        if raw_key is None:
            return self._security_scanner_structured_document_values(
                child,
                allowed_keys,
                use_workers=False,
            )
        return self._security_scanner_structured_document_child_values_for_entry(
            raw_key,
            child,
            allowed_keys,
        )

    def _security_scanner_structured_document_child_values_for_entry(
        self,
        raw_key: Any,
        child: Any,
        allowed_keys: set[str],
    ) -> list[str]:
        values: list[str] = []
        key = self._yaml_key_fingerprint(str(raw_key or ""))
        if key in allowed_keys:
            values.extend(self._security_scanner_structured_value_values(child))
        if isinstance(child, (dict, list)):
            values.extend(
                self._security_scanner_structured_document_values(
                    child,
                    allowed_keys,
                    use_workers=False,
                )
            )
        return values[:4096]

    def _security_scanner_structured_value_values(self, value: Any) -> list[str]:
        if isinstance(value, (str, int, float)):
            candidate = str(value).strip()
            return [candidate] if candidate else []
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:4096]:
                values.extend(self._security_scanner_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        if isinstance(value, dict):
            values = []
            for item in list(value.values())[:4096]:
                values.extend(self._security_scanner_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        return []

    @staticmethod
    def _security_scanner_config_candidate_entry(raw_value: Any) -> str:
        value = ArtifactQueueProcessor._parse_key_value_scalar(str(raw_value or "").strip())
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _recon_tool_output_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not _recon_tool_output_artifact_label(source_hint):
            return ""

        allowed_keys = {
            "a",
            "aaaa",
            "base_uri",
            "data",
            "domain",
            "domains",
            "endpoint",
            "endpoints",
            "finalurl",
            "final_url",
            "fqdn",
            "fqdnname",
            "host",
            "hostname",
            "hostnames",
            "hosts",
            "input",
            "ip",
            "ipaddress",
            "ip_address",
            "ip_str",
            "ipv4",
            "ipv6",
            "ips",
            "items",
            "matches",
            "location",
            "matched",
            "matchedat",
            "matchedurl",
            "name",
            "observed_name",
            "observed_url",
            "origin",
            "origin_url",
            "page_url",
            "path",
            "port",
            "records",
            "requesturl",
            "redirect",
            "redirectlocation",
            "results",
            "responseurl",
            "baseurl",
            "scanurl",
            "services",
            "site",
            "siteurl",
            "subdomain",
            "subdomains",
            "target",
            "targethost",
            "targethostname",
            "targets",
            "targeturl",
            "templateurl",
            "uri",
            "url",
            "urls",
            "webserver",
            "web_url",
            "weburl",
        }
        allowed_keys = {self._yaml_key_fingerprint(key) for key in allowed_keys}

        raw_candidates: list[str] = []

        def _append_candidate(raw_value: str) -> None:
            if len(raw_candidates) >= 4096:
                return
            value = self._parse_key_value_scalar(str(raw_value or "").strip())
            if not value:
                return
            raw_candidates.append(value)

        raw_text = str(text or "").strip()
        document = _safe_json_loads(raw_text)
        if isinstance(document, (dict, list)):
            for candidate in self._recon_tool_output_structured_document_values(
                document,
                allowed_keys,
                use_workers=True,
            ):
                _append_candidate(candidate)

        if "<" in raw_text and ">" in raw_text:
            for tag_match in re.finditer(
                r"<\s*([A-Za-z0-9_.:-]+)(?:\s[^>]*)?>([^<>]{1,4096})<\s*/\s*\1\s*>",
                raw_text,
                re.IGNORECASE,
            ):
                key = self._yaml_key_fingerprint(str(tag_match.group(1) or ""))
                if key not in allowed_keys:
                    continue
                value = html.unescape(str(tag_match.group(2) or "").strip())
                if value:
                    _append_candidate(value)

        line_candidate_batches = self._run_ordered_local_batch(
            [(raw_line, allowed_keys) for raw_line in raw_text.splitlines()[:4096]],
            self._recon_tool_output_line_candidate_values,
            default_factory=list,
        )
        for line_candidate_batch in line_candidate_batches:
            for candidate in line_candidate_batch:
                _append_candidate(candidate)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._recon_tool_output_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _recon_tool_output_line_candidate_values(
        self,
        line_job: tuple[str, set[str]],
    ) -> list[str]:
        raw_line, allowed_keys = line_job
        line = str(raw_line or "").strip()
        if not line or line.startswith(("#", "//")):
            return []
        line_document = _safe_json_loads(line)
        if isinstance(line_document, (dict, list)):
            return self._recon_tool_output_structured_document_values(
                line_document,
                allowed_keys,
                use_workers=False,
            )
        first_field = re.split(r"[\t, ]+", line, maxsplit=1)[0].strip()
        return [first_field] if first_field else []

