    def _maven_xml_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "").strip()
        if not raw_text or "<" not in raw_text or ">" not in raw_text:
            return ""
        source_label = _maven_xml_config_artifact_label(source_hint)
        if not source_label and not re.search(r"<\s*(?:project|settings)\b", raw_text, re.IGNORECASE):
            return ""

        try:
            root = ElementTree.fromstring(raw_text)
        except ElementTree.ParseError:
            if not source_label:
                return ""
            raw_values = self._maven_xml_tag_text_fallback_values(raw_text)
        else:
            if not self._maven_xml_root_looks_supported(root, source_hint=source_hint):
                return ""
            raw_values = self._maven_xml_urlish_values(root)

        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._maven_xml_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @classmethod
    def _maven_xml_root_looks_supported(
        cls,
        root: ElementTree.Element,
        *,
        source_hint: str,
    ) -> bool:
        if _maven_xml_config_artifact_label(source_hint):
            return True
        root_tag = cls._xml_local_name(root.tag)
        tags = {cls._xml_local_name(element.tag) for element in root.iter()}
        if root_tag == "project":
            return bool(
                tags
                & {
                    "artifactid",
                    "build",
                    "developers",
                    "distributionmanagement",
                    "groupid",
                    "modelversion",
                    "pluginrepositories",
                    "repositories",
                    "scm",
                }
            )
        if root_tag == "settings":
            return bool(tags & {"localrepository", "mirrors", "pluginGroups", "profiles", "servers"})
        return False

    @classmethod
    def _maven_xml_urlish_values(cls, root: ElementTree.Element) -> list[str]:
        values: list[str] = []
        for element in root.iter():
            tag = cls._xml_local_name(element.tag)
            if tag not in {"connection", "developerconnection", "url"}:
                continue
            value = "".join(element.itertext()).strip()
            if value:
                values.append(value)
        return values

    @staticmethod
    def _maven_xml_tag_text_fallback_values(text: str) -> list[str]:
        return [
            str(match.group("value") or "").strip()
            for match in re.finditer(
                r"""
                <\s*(?:url|connection|developerConnection)\b[^>]*>
                (?P<value>.*?)
                <\s*/\s*(?:url|connection|developerConnection)\s*>
                """,
                str(text or ""),
                re.IGNORECASE | re.DOTALL | re.VERBOSE,
            )
        ]

    @staticmethod
    def _xml_local_name(tag: object) -> str:
        value = str(tag or "").strip()
        if "}" in value:
            value = value.rsplit("}", 1)[-1]
        if ":" in value:
            value = value.rsplit(":", 1)[-1]
        return value.lower()

    @staticmethod
    def _maven_xml_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        direct_match = re.search(r"https?://[^\s<>()\"']+", value, re.IGNORECASE)
        if direct_match:
            return _artifact_package_registry_url_candidate(direct_match.group(0))
        return _artifact_package_registry_host_or_url_candidate(value)

    def _gradle_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "")
        if not raw_text.strip():
            return ""
        source_label = _gradle_text_config_artifact_label(source_hint)
        source_name = Path(str(source_hint or "").replace("\\", "/")).name.lower()
        if not source_label and Path(source_name).suffix not in {".gradle", ".kts"}:
            return ""
        lowered = raw_text.lower()
        if not source_label and not any(
            marker in lowered
            for marker in (
                "dependencyresolutionmanagement",
                "pluginmanagement",
                "repositories",
                "maven(",
                "maven {",
            )
        ):
            return ""

        raw_values = self._gradle_text_repository_values(raw_text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._gradle_text_repository_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _gradle_text_repository_values(text: str) -> list[str]:
        return gradle_text_repository_values(text)

    @staticmethod
    def _gradle_text_repository_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

