    @staticmethod
    def _api_client_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    def _http_request_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not self._http_request_text_source_looks_supported(source_hint):
            return ""
        raw_values = self._http_request_text_candidate_values(text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._http_request_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _http_request_text_source_looks_supported(source_hint: str) -> bool:
        suffix = Path(str(source_hint or "").replace("\\", "/")).suffix.lower()
        return suffix in {".http", ".rest", ".hurl"}

    def _http_request_text_candidate_values(self, text: str) -> list[str]:
        line_entries = self._run_ordered_local_batch(
            str(text or "").splitlines()[:4096],
            self._http_request_text_line_candidate_value,
            default_factory=str,
        )
        return [str(value or "").strip() for value in line_entries if str(value or "").strip()]

    @staticmethod
    def _http_request_text_line_candidate_value(raw_line: str) -> str:
        line = str(raw_line or "").strip()
        if not line or line.startswith(("#", "//", "--")):
            return ""
        request_match = re.match(
            r"""
            ^\s*
            (?P<method>GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS|TRACE)
            \s+
            (?P<target>[^\s#]+)
            """,
            line,
            re.IGNORECASE | re.VERBOSE,
        )
        if request_match:
            return str(request_match.group("target") or "").strip()
        variable_match = re.match(
            r"""
            ^\s*@?
            (?P<key>[A-Za-z0-9_.\-]*?(?:url|uri|host|hostname|domain|endpoint|baseurl|baseuri)[A-Za-z0-9_.\-]*)
            \s*[:=]\s*
            (?P<value>[^\s#]+)
            """,
            line,
            re.IGNORECASE | re.VERBOSE,
        )
        if variable_match:
            return str(variable_match.group("value") or "").strip().strip("\"'")
        return ""

    @staticmethod
    def _http_request_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    def _http_transcript_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not parse_text.strip():
            return ""
        if not self._http_transcript_text_source_looks_supported(source_hint):
            return ""
        if not self._http_transcript_text_looks_supported(parse_text):
            return ""
        raw_values = self._http_transcript_text_candidate_values(parse_text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._http_transcript_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _http_transcript_text_source_looks_supported(source_hint: str) -> bool:
        normalized = str(source_hint or "").replace("\\", "/").lower()
        if not normalized:
            return False
        suffix = Path(normalized).suffix.lower()
        if suffix in {".http", ".rest"}:
            return True
        if ".saz/" in normalized or normalized.endswith(".saz"):
            return True
        if "#pcap-strings" in normalized:
            return True
        if re.search(r"(?:^|/)(?:raw/)?\d+_[cs]\.txt$", normalized):
            return True
        return bool(
            re.search(
                r"(?:^|/)(?:request|response|session|http)[-_]?(?:raw|headers)?\.txt$",
                normalized,
            )
        )

    @staticmethod
    def _http_transcript_text_looks_supported(text: str) -> bool:
        sample = str(text or "")[:16384]
        if _HTTP_TRANSCRIPT_REQUEST_LINE_RE.search(sample):
            return True
        return bool(re.search(r"(?im)^\s*HTTP/\d(?:\.\d)?\s+\d{3}\b", sample))

    def _http_transcript_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        values: list[str] = []
        for match in _HTTP_TRANSCRIPT_URL_FIELD_RE.finditer(parse_text):
            field_value = str(match.group("value") or "").strip().strip("\"'")
            if field_value:
                values.append(field_value)

        current_host = ""
        current_scheme = ""
        pending_targets: list[str] = []

        def flush_pending() -> None:
            nonlocal pending_targets
            if not current_host or not pending_targets:
                return
            for target in pending_targets:
                candidate = self._http_transcript_absolute_url(
                    target,
                    host=current_host,
                    scheme=current_scheme,
                )
                if candidate:
                    values.append(candidate)
            pending_targets = []

        for raw_line in parse_text.splitlines()[:4096]:
            line = raw_line.strip()
            if not line:
                current_host = ""
                current_scheme = ""
                pending_targets = []
                continue

            request_match = _HTTP_TRANSCRIPT_REQUEST_LINE_RE.match(line)
            if request_match:
                method = str(request_match.group("method") or "").upper()
                target = str(request_match.group("target") or "").strip()
                if method == "CONNECT":
                    connect_host = self._http_transcript_host_candidate(target)
                    if connect_host:
                        current_host = connect_host
                        current_scheme = "https"
                        values.append(f"https://{connect_host}")
                    continue
                if target.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
                    values.append(target)
                    parsed_target = urlparse(target if "://" in target else f"https:{target}")
                    if parsed_target.netloc:
                        current_host = parsed_target.netloc
                    if parsed_target.scheme:
                        current_scheme = parsed_target.scheme
                    continue
                if target.startswith("/"):
                    if current_host:
                        candidate = self._http_transcript_absolute_url(
                            target,
                            host=current_host,
                            scheme=current_scheme,
                        )
                        if candidate:
                            values.append(candidate)
                    else:
                        pending_targets.append(target)
                    continue

            header_match = _HTTP_TRANSCRIPT_HEADER_RE.match(line)
            if not header_match:
                continue
            name = str(header_match.group("name") or "").strip().lower()
            value = str(header_match.group("value") or "").strip().strip("\"'")
            if not value:
                continue
            if name in {"host", ":authority", "x-forwarded-host"}:
                host = self._http_transcript_host_candidate(value)
                if host:
                    current_host = host
                    flush_pending()
                continue
            if name in {":scheme", "x-forwarded-proto", "x-forwarded-protocol"}:
                scheme = self._http_transcript_scheme_candidate(value)
                if scheme:
                    current_scheme = scheme
                    flush_pending()
                continue
            if name in {
                "location",
                "content-location",
                "origin",
                "referer",
                "referrer",
                "x-original-url",
                "x-rewrite-url",
                "x-forwarded-uri",
                "x-forwarded-url",
            }:
                if value.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
                    values.append(value)
                elif value.startswith("/") and current_host:
                    candidate = self._http_transcript_absolute_url(
                        value,
                        host=current_host,
                        scheme=current_scheme,
                    )
                    if candidate:
                        values.append(candidate)

        return values[:512]

    @staticmethod
    def _http_transcript_host_candidate(value: str) -> str:
        candidate = str(value or "").strip().strip("\"'")
        if not candidate:
            return ""
        candidate = candidate.split(",", 1)[0].strip()
        candidate = candidate.split(";", 1)[0].strip()
        candidate = re.sub(r"^\w+://", "", candidate).strip("/")
        candidate = candidate.split("/", 1)[0].strip()
        candidate = candidate.split("@", 1)[-1].strip()
        if not candidate or re.search(r"\s", candidate):
            return ""
        return candidate

    @staticmethod
    def _http_transcript_scheme_candidate(value: str) -> str:
        scheme = str(value or "").strip().lower().split(",", 1)[0].strip()
        if scheme in {"http", "https", "ws", "wss"}:
            return scheme
        return ""

    def _http_transcript_absolute_url(
        self,
        target: str,
        *,
        host: str,
        scheme: str = "",
    ) -> str:
        host_candidate = self._http_transcript_host_candidate(host)
        if not host_candidate:
            return ""
        target_value = str(target or "").strip()
        if not target_value or target_value == "*":
            return ""
        if target_value.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
            return target_value
        if not target_value.startswith("/"):
            return ""
        url_scheme = self._http_transcript_scheme_candidate(scheme)
        if not url_scheme:
            lowered_host = host_candidate.lower()
            url_scheme = "http" if lowered_host.endswith(":80") else "https"
        return f"{url_scheme}://{host_candidate}{target_value}"

    @staticmethod
    def _http_transcript_url_candidate_entry(raw_value: str) -> str:
        candidate = _normalize_artifact_text_url(str(raw_value or "").strip().strip("\"'"))
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(candidate)

    def _structured_payload_lines(
        self,
        raw_values: Sequence[str],
        normalizer: Callable[[str], str],
        *,
        casefold_seen: bool,
    ) -> str:
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            normalizer,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            key = normalized.lower() if casefold_seen else normalized
            if not normalized or key in seen:
                continue
            seen.add(key)
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _ssh_payload_entry(raw_value: str) -> str:
        candidate = str(raw_value or "").strip().strip("[]")
        return f"ssh://{candidate}" if candidate else ""

