    def _yaml_kubernetes_secret_manifest_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> list[str]:
        kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        api_version = self._yaml_ref_value(normalized, "apiVersion", "api_version").lower()
        if kind == "secretproviderclass":
            return secret_provider_class_candidates(mapping)
        external_secret_kinds = {
            "externalsecret",
            "clusterexternalsecret",
            "secretstore",
            "clustersecretstore",
            "pushsecret",
        }
        if not (
            kind in external_secret_kinds
            or (kind == "sealedsecret" and "bitnami.com" in api_version)
            or (kind in external_secret_kinds and "external-secrets.io" in api_version)
        ):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        object_identifier = self._yaml_kubernetes_object_identifier(mapping)
        if object_identifier:
            object_uri = {
                "externalsecret": "external-secret",
                "clusterexternalsecret": "external-secret",
                "secretstore": "secret-store",
                "clustersecretstore": "cluster-secret-store",
                "pushsecret": "external-secret",
                "sealedsecret": "sealed-secret",
            }.get(kind)
            if object_uri:
                _append(f"{object_uri}://{object_identifier}")

        if kind == "sealedsecret":
            return candidates

        spec = self._yaml_child_mapping(mapping, "spec")
        spec_mappings = [spec] if spec else []
        external_secret_spec = self._yaml_child_mapping(spec, "externalSecretSpec", "external_secret_spec")
        if external_secret_spec:
            spec_mappings.append(external_secret_spec)

        remote_keys: list[str] = []
        for spec_mapping in spec_mappings:
            remote_keys.extend(self._yaml_external_secret_remote_ref_keys(spec_mapping))
            for store_ref in self._yaml_external_secret_store_refs(spec_mapping, object_identifier):
                _append(store_ref)
            provider = self._yaml_child_mapping(spec_mapping, "provider")
            for provider_candidate in self._yaml_external_secret_provider_candidates(provider, remote_keys):
                _append(provider_candidate)

        for remote_key in remote_keys:
            encoded_key = self._yaml_external_secret_ref_segment(remote_key)
            if encoded_key:
                _append(f"external-secret://remote-ref/{encoded_key}")

        return candidates

