    def _yaml_structured_candidates_from_env_map(
        self,
        env_map: dict[str, str],
        *,
        source_hint: str = "",
    ) -> list[str]:
        if not env_map:
            return []
        candidate_batches = self._run_ordered_local_batch(
            (
                "firebase",
                "supabase",
                "s3",
                "gcs",
                "do_spaces",
                "azure",
                "managed_hosting",
                "cloudflare",
                "amplify_client_config",
                "sanity",
                "docker_auth",
                "restic",
                "borg",
                "duplicati",
                "env_values",
            ),
            lambda family: self._yaml_env_candidate_family(
                env_map,
                family,
                source_hint=source_hint,
            ),
            default_factory=list,
        )
        candidate_entry_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._yaml_candidate_batch_entries,
            default_factory=list,
        )
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(candidate_entry_batches)),
            self._yaml_candidate_family_entries,
            default_factory=list,
        )
        prepared_candidate_entries = self._run_ordered_local_batch(
            [
                (candidate_index, candidate)
                for candidate_index, candidate in enumerate(
                    candidate
                    for candidate_family in prepared_candidate_families
                    for candidate in candidate_family
                )
            ],
            self._yaml_candidate_merge_entry,
            default_factory=lambda: None,
        )
        return [candidate for candidate in prepared_candidate_entries if isinstance(candidate, str)]

