    def _extract_calendar_contact_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        return self._extract_calendar_contact_bytes_payloads(
            path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
            str(path),
            path.name,
        )

    def _extract_calendar_contact_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        text = self._decode_text_artifact_bytes(data)
        if not text:
            return []
        unfolded = self._unfold_calendar_contact_text(text)
        summary_lines = self._calendar_contact_summary_lines(unfolded)
        payloads: list[tuple[str, str, str]] = []
        if summary_lines:
            payloads.append(
                (
                    source_file,
                    f"{member_name}#calendar-contact-summary",
                    "\n".join(summary_lines),
                )
            )
        if unfolded:
            payloads.append((source_file, member_name, unfolded))
        return payloads

    @staticmethod
    def _unfold_calendar_contact_text(text: str) -> str:
        lines = str(text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
        unfolded: list[str] = []
        for line in lines:
            if line.startswith((" ", "\t")) and unfolded:
                unfolded[-1] += line[1:]
                continue
            unfolded.append(line.rstrip())
        return "\n".join(unfolded).strip()

    @staticmethod
    def _calendar_contact_summary_lines(text: str) -> list[str]:
        line_candidates = ArtifactQueueProcessor._run_ordered_static_batch(
            str(text or "").splitlines(),
            ArtifactQueueProcessor._calendar_contact_summary_line_entry,
            default_factory=lambda: None,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for summary_line in line_candidates:
            if not summary_line:
                continue
            if summary_line in seen:
                continue
            seen.add(summary_line)
            lines.append(summary_line)
            if len(lines) >= 80:
                break
        return lines

    @staticmethod
    def _calendar_contact_summary_line_entry(raw_line: str) -> str | None:
        interesting_keys = {
            "BEGIN",
            "FN",
            "N",
            "ORG",
            "TITLE",
            "SUMMARY",
            "DESCRIPTION",
            "EMAIL",
            "TEL",
            "URL",
            "LOCATION",
            "ATTENDEE",
            "ORGANIZER",
        }
        line = str(raw_line or "").strip()
        if not line or ":" not in line:
            return None
        key_part, raw_value = line.split(":", 1)
        key = key_part.split(";", 1)[0].strip().upper()
        if key not in interesting_keys:
            return None
        value = raw_value.strip()
        if key in {"ATTENDEE", "ORGANIZER"} and value.lower().startswith("mailto:"):
            value = value[7:].strip()
        if not value:
            return None
        if len(value) > 1024:
            value = value[:1024].rstrip()
        return f"{key.lower()}={value}"

    def _extract_pdf_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        return _orchestration_extract_pdf_payloads(
            data,
            source_file=str(path),
            member_name=path.name,
            run_ordered_batch=self._run_ordered_local_batch,
            extract_pdf_payload_fragment=lambda family, data, source_file, member_name: (
                self._extract_pdf_payload_fragment(
                    family,
                    data=data,
                    source_file=source_file,
                    member_name=member_name,
                    path=path,
                )
            ),
            artifact_payload_tuple_batch_entries=self._artifact_payload_tuple_batch_entries,
        )

    def _extract_pdf_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        return _orchestration_extract_pdf_payloads(
            bounded,
            source_file=source_file,
            member_name=member_name,
            run_ordered_batch=self._run_ordered_local_batch,
            extract_pdf_payload_fragment=lambda family, data, source_file, member_name: (
                self._extract_pdf_payload_fragment(
                    family,
                    data=data,
                    source_file=source_file,
                    member_name=member_name,
                )
            ),
            artifact_payload_tuple_batch_entries=self._artifact_payload_tuple_batch_entries,
        )

    def _extract_pdf_payload_fragment(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
        path: Path | None = None,
    ) -> list[tuple[str, str, str]]:
        def _extract_text_payloads(
            fragment_data: bytes,
            fragment_source_file: str,
            fragment_member_name: str,
        ) -> list[tuple[str, str, str]]:
            if path is not None:
                return self._extract_pdf_text_payloads_from_path(path)
            return self._extract_pdf_text_payloads_from_bytes(
                fragment_data,
                source_file=fragment_source_file,
                member_name=fragment_member_name,
            )

        def _extract_ocr_payloads(
            fragment_data: bytes,
            fragment_source_file: str,
            fragment_member_name: str,
        ) -> list[tuple[str, str, str]]:
            if path is not None:
                return self._extract_pdf_ocr_payloads(path)
            return self._extract_pdf_bytes_ocr_payloads(
                fragment_data,
                fragment_source_file,
                fragment_member_name,
            )

        return _orchestration_extract_pdf_payload_fragment(
            family,
            data=data,
            source_file=source_file,
            member_name=member_name,
            extract_pdf_text_payloads=_extract_text_payloads,
            pdf_metadata_lines=self._pdf_metadata_lines,
            pdf_xmp_payload=self._pdf_xmp_payload,
            extract_pdf_ocr_payloads=_extract_ocr_payloads,
        )

    def _extract_pdf_text_payloads_from_path(
        self,
        path: Path,
    ) -> list[tuple[str, str, str]]:
        return _orchestration_extract_pdf_text_payloads_from_path(
            path,
            path_exists=Path.exists,
            read_text=self._read_text,
        )

    def _extract_pdf_text_payloads_from_bytes(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        return _orchestration_extract_pdf_text_payloads_from_bytes(
            data,
            source_file=source_file,
            member_name=member_name,
            max_artifact_member_bytes=_MAX_ARTIFACT_MEMBER_BYTES,
        )

    def _extract_sqlite_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        try:
            con = direct_connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        except sqlite3.Error:
            return [(str(path), path.name, self._read_text(path))]
        try:
            payloads = self._extract_sqlite_connection_payloads(
                con,
                str(path),
                path.name,
            )
        finally:
            con.close()
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_sqlite_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        suffix = Path(member_name).suffix or ".sqlite"
        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                temp_path = Path(temp_dir) / f"artifact{suffix}"
                temp_path.write_bytes(bounded)
                con = direct_connect(f"file:{temp_path.as_posix()}?mode=ro", uri=True)
                try:
                    payloads = self._extract_sqlite_connection_payloads(
                        con,
                        source_file,
                        member_name,
                    )
                finally:
                    con.close()
        except Exception:  # noqa: BLE001
            payloads = []
        return payloads or self._member_payloads(source_file, member_name, bounded)

    def _extract_emlx_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_emlx_bytes_payloads(
            data,
            str(path),
            path.name,
            depth=depth,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_emlx_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        message_bytes = self._emlx_message_bytes(data)
        if not message_bytes:
            return self._member_payloads(source_file, member_name, data)
        return self._extract_email_message_payloads(
            message_bytes[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            member_name,
            depth=depth,
        )

    @staticmethod
    def _emlx_message_bytes(data: bytes) -> bytes:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return b""
        match = re.match(rb"\s*(\d+)\r?\n", bounded[:128])
        if not match:
            return bounded
        start = match.end()
        remaining = bounded[start:]
        if not remaining:
            return b""
        try:
            declared_length = int(match.group(1))
        except (TypeError, ValueError):
            return remaining
        if declared_length <= 0:
            return remaining
        if declared_length <= len(remaining):
            return remaining[:declared_length]
        return remaining

    def _extract_msg_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_msg_bytes_payloads(
            data,
            str(path),
            path.name,
            depth=depth,
        )
        return payloads or self._extract_legacy_document_payloads(path, depth=depth)

    def _extract_msg_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        try:
            import olefile  # noqa: PLC0415
        except Exception:  # noqa: BLE001
            return self._extract_legacy_binary_payloads(
                bounded,
                source_file,
                member_name,
                depth=depth,
            )
        try:
            with olefile.OleFileIO(BytesIO(bounded)) as ole:
                payloads = self._extract_msg_ole_payloads(
                    ole,
                    source_file,
                    member_name,
                    depth=depth,
                )
        except Exception:  # noqa: BLE001
            payloads = []
        if payloads:
            return payloads
        return self._extract_legacy_binary_payloads(
            bounded,
            source_file,
            member_name,
            depth=depth,
        )

    def _extract_msg_ole_payloads(
        self,
        ole: Any,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        summary_lines: list[str] = []
        attachments: dict[str, dict[str, Any]] = {}

        try:
            stream_parts_list = ole.listdir(streams=True, storages=False)
        except Exception:  # noqa: BLE001
            return []

        summary_lines.extend(self._ole_metadata_lines(ole))

        raw_property_entries: list[tuple[tuple[Any, ...], bytes]] = []
        for stream_parts in stream_parts_list:
            if not stream_parts:
                continue
            stream_name = str(stream_parts[-1] or "").strip()
            if not _MSG_PROPERTY_STREAM_RE.fullmatch(stream_name):
                continue
            try:
                stream_data = ole.openstream(stream_parts).read(_MAX_ARTIFACT_MEMBER_BYTES)
            except Exception:  # noqa: BLE001
                continue
            raw_property_entries.append((tuple(stream_parts), stream_data))
        property_entries = self._run_ordered_local_batch(
            raw_property_entries,
            self._msg_ole_property_entry,
            default_factory=lambda: None,
        )
        property_entries = [
            property_entry
            for property_entry in property_entries
            if isinstance(property_entry, tuple)
        ]
        job_batches = self._run_ordered_local_batch(
            property_entries,
            lambda property_entry: self._msg_ole_property_stream_job(
                property_entry,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        property_jobs = [
            job
            for job in job_batches
            if isinstance(job, MsgOLEPropertyJob)
        ]

        ordered_property_results = self._run_ordered_local_batch(
            property_jobs,
            self._extract_msg_ole_property_job,
            default_factory=MsgOLEPropertyResult,
        )

        for result in ordered_property_results:
            if result is None:
                continue
            payloads.extend(result.payloads)
            summary_lines.extend(result.summary_lines)
            if result.attachment_storage:
                attachment = attachments.setdefault(result.attachment_storage, {})
                for key, value in result.attachment_updates:
                    attachment[key] = value

        attachment_jobs: list[MsgAttachmentExtractionJob] = []
        if depth < 2 and attachments:
            built_attachment_jobs = self._run_ordered_local_batch(
                list(enumerate(attachments.values(), start=1)),
                lambda attachment_job: self._build_msg_attachment_job(
                    attachment_job,
                    source_file=source_file,
                    member_name=member_name,
                    depth=depth,
                ),
                default_factory=lambda: None,
            )
            attachment_jobs = [job for job in built_attachment_jobs if job is not None]

        payload_families = self._run_ordered_local_batch(
            ("summary", "attachments"),
            lambda family: self._extract_msg_post_property_payload_family(
                family,
                summary_lines=summary_lines,
                attachment_jobs=attachment_jobs,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        family_head_payloads = prepared_payload_families[0] if prepared_payload_families else []
        family_tail_payloads = prepared_payload_families[1] if len(prepared_payload_families) > 1 else []
        return [*family_head_payloads, *payloads, *family_tail_payloads]

    @staticmethod
    def _msg_ole_property_entry(
        property_entry: tuple[Sequence[Any], bytes],
    ) -> tuple[tuple[Any, ...], bytes] | None:
        stream_parts, stream_data = property_entry
        normalized_parts = tuple(stream_parts)
        if not normalized_parts or not stream_data:
            return None
        return normalized_parts, bytes(stream_data)

    def _msg_ole_property_stream_job(
        self,
        property_entry: tuple[Sequence[Any], bytes],
        *,
        source_file: str,
        member_name: str,
    ) -> MsgOLEPropertyJob | None:
        stream_parts, stream_data = property_entry
        if not stream_parts or not stream_data:
            return None
        stream_name = str(stream_parts[-1] or "").strip()
        match = _MSG_PROPERTY_STREAM_RE.fullmatch(stream_name)
        if not match:
            return None
        prop_id, prop_type = (group.upper() for group in match.groups())
        attachment_storage = next(
            (
                str(part or "").strip()
                for part in stream_parts[:-1]
                if str(part or "").strip().startswith(_MSG_ATTACHMENT_STORAGE_PREFIX)
            ),
            "",
        )
        label = _MSG_PROPERTY_LABELS.get(prop_id, f"prop_{prop_id.lower()}")
        return MsgOLEPropertyJob(
            source_file=source_file,
            member_name=member_name,
            attachment_storage=attachment_storage,
            label=label,
            prop_id=prop_id,
            prop_type=prop_type,
            stream_data=stream_data,
        )

    def _extract_msg_post_property_payload_family(
        self,
        family: str,
        *,
        summary_lines: Sequence[str],
        attachment_jobs: Sequence[MsgAttachmentExtractionJob],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_msg_summary_payloads(
                summary_lines,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "attachments":
            return self._extract_msg_attachment_job_payloads(attachment_jobs)
        return []

    def _extract_msg_summary_payloads(
        self,
        summary_lines: Sequence[str],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not summary_lines:
            return []
        return [(source_file, f"{member_name}#msg-meta", "\n".join(summary_lines[:256]))]

    def _extract_msg_attachment_job_payloads(
        self,
        attachment_jobs: Sequence[MsgAttachmentExtractionJob],
    ) -> list[tuple[str, str, str]]:
        if not attachment_jobs:
            return []
        ordered_attachment_payloads = self._run_ordered_local_batch(
            attachment_jobs,
            self._extract_msg_attachment_payloads,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (attachment_index, attachment_payloads or [])
                for attachment_index, attachment_payloads in enumerate(ordered_attachment_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for attachment_payloads in prepared_payloads:
            payloads.extend(attachment_payloads)
        return payloads

    def _build_msg_attachment_job(
        self,
        attachment_job: tuple[int, dict[str, Any]],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> MsgAttachmentExtractionJob | None:
        index, attachment = attachment_job
        attachment_data = attachment.get("data")
        if not isinstance(attachment_data, (bytes, bytearray)) or not attachment_data:
            return None
        attachment_name = self._msg_attachment_name(attachment, index)
        if not attachment_name:
            return None
        return MsgAttachmentExtractionJob(
            source_file=source_file,
            member_name=member_name,
            attachment_name=attachment_name,
            attachment_data=bytes(attachment_data)[:_MAX_ARTIFACT_MEMBER_BYTES],
            depth=depth + 1,
        )

    def _extract_msg_ole_property_job(
        self,
        job: MsgOLEPropertyJob,
    ) -> MsgOLEPropertyResult:
        if job.attachment_storage:
            if job.prop_id == "3701":
                return MsgOLEPropertyResult(
                    attachment_storage=job.attachment_storage,
                    attachment_updates=[
                        ("data", job.stream_data),
                        ("data_type", job.prop_type),
                    ],
                )
            attachment_text = self._msg_property_text(job.prop_id, job.prop_type, job.stream_data)
            if not attachment_text:
                return MsgOLEPropertyResult()
            return MsgOLEPropertyResult(
                attachment_storage=job.attachment_storage,
                attachment_updates=[(job.label, attachment_text)],
            )

        property_text = self._msg_property_text(job.prop_id, job.prop_type, job.stream_data)
        if not property_text:
            return MsgOLEPropertyResult()
        if job.prop_id in {"1000", "1013"}:
            suffix = ".html" if job.prop_id == "1013" or "<html" in property_text.lower() else ".txt"
            return MsgOLEPropertyResult(
                payloads=[
                    (
                        job.source_file,
                        f"{job.member_name}#msg-{job.label}{suffix}",
                        property_text,
                    )
                ]
            )
        return MsgOLEPropertyResult(summary_lines=[f"{job.label}={property_text}"])

    def _extract_msg_attachment_payloads(
        self,
        job: MsgAttachmentExtractionJob,
    ) -> list[tuple[str, str, str]]:
        return self._extract_member_data_payloads(
            job.attachment_data,
            job.source_file,
            f"{job.member_name}/{job.attachment_name}",
            depth=job.depth,
        )

    def _msg_property_text(
        self,
        prop_id: str,
        prop_type: str,
        data: bytes,
    ) -> str:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return ""
        if prop_type == "001F":
            return bounded.decode("utf-16-le", errors="ignore").replace("\x00", "").strip()
        if prop_type == "001E":
            return self._decode_text_artifact_bytes(bounded)
        if prop_type == "0102" and prop_id in {"007D", "1000", "1013"}:
            return self._decode_text_artifact_bytes(bounded)
        return ""

    @staticmethod
    def _msg_attachment_name(attachment: dict[str, Any], index: int) -> str:
        for key in ("attachment_long_filename", "attachment_filename"):
            candidate = Path(str(attachment.get(key) or "").strip()).name
            if candidate:
                return candidate
        mime_tag = str(attachment.get("attachment_mime_tag") or "").strip().lower()
        suffix = _suffix_from_content_type(mime_tag) if mime_tag else ""
        if suffix:
            return f"attachment-{index}{suffix}"
        attachment_data = attachment.get("data")
        if isinstance(attachment_data, (bytes, bytearray)) and attachment_data:
            inferred_suffix = ArtifactQueueProcessor._msg_attachment_suffix_from_data(
                bytes(attachment_data)[:_MAX_ARTIFACT_MEMBER_BYTES]
            )
            if inferred_suffix:
                return f"attachment-{index}{inferred_suffix}"
        return ""

    @staticmethod
    def _msg_attachment_suffix_from_data(data: bytes) -> str:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return ""
        if zipfile.is_zipfile(BytesIO(bounded)):
            return ".zip"
        if bounded.startswith(_OLE_MAGIC):
            return ".msg"
        if bounded.startswith(b"%PDF-"):
            return ".pdf"
        if ArtifactQueueProcessor._looks_like_archive_bytes(bounded):
            return ".zip"
        text_sample = ArtifactQueueProcessor._decode_text_artifact_bytes(bounded[:8192])
        if text_sample and (
            "=" in text_sample
            or "@" in text_sample
            or "http://" in text_sample.lower()
            or "https://" in text_sample.lower()
        ):
            return ".txt"
        return ""

    @staticmethod
    def _looks_like_pcap_bytes(data: bytes, member_name: str = "") -> bool:
        lowered = str(member_name or "").strip().lower()
        if lowered.endswith(tuple(_PCAP_SUFFIXES)) or any(f"{suffix}#" in lowered for suffix in _PCAP_SUFFIXES):
            return True
        return data[:4] in _PCAP_CLASSIC_MAGICS or data[:4] == _PCAPNG_MAGIC

    def _extract_pcap_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        return self._extract_pcap_bytes_payloads(
            path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
            str(path),
            path.name,
        )

    def _extract_pcap_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._looks_like_pcap_bytes(data, member_name):
            return self._member_payloads(source_file, member_name, data)
        payload_fragments = self._run_ordered_local_batch(
            ("summary", "strings"),
            lambda family: self._extract_pcap_payload_family(
                family,
                data=data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_fragments = self._run_ordered_local_batch(
            list(enumerate(payload_fragments)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for fragment in prepared_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_pcap_payload_family(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            summary_lines = self._pcap_summary_lines(data, member_name)
            if summary_lines:
                return [(source_file, f"{member_name}#pcap-summary", "\n".join(summary_lines))]
            return []
        if family == "strings":
            strings_payload = self._binary_string_payload(data)
            if strings_payload:
                return [(source_file, f"{member_name}#pcap-strings", strings_payload)]
            return []
        return []

    def _pcap_summary_lines(self, data: bytes, member_name: str) -> list[str]:
        if data[:4] == _PCAPNG_MAGIC:
            return self._pcapng_summary_lines(data)
        if data[:4] in _PCAP_CLASSIC_MAGICS:
            return self._pcap_classic_summary_lines(data)
        if Path(member_name.lower()).suffix == ".pcapng":
            return ["format=pcapng"]
        return ["format=pcap"]

    @staticmethod
    def _pcap_classic_summary_lines(data: bytes) -> list[str]:
        endian = _PCAP_CLASSIC_MAGICS.get(data[:4])
        if not endian or len(data) < 24:
            return ["format=pcap"]
        try:
            version_major, version_minor, _thiszone, _sigfigs, snaplen, linktype = struct.unpack(
                f"{endian}HHIIII",
                data[4:24],
            )
        except struct.error:
            return ["format=pcap"]
        packet_count = 0
        captured_bytes = 0
        offset = 24
        while offset + 16 <= len(data) and packet_count < 1024:
            try:
                _ts_sec, _ts_usec, incl_len, _orig_len = struct.unpack(
                    f"{endian}IIII",
                    data[offset : offset + 16],
                )
            except struct.error:
                break
            offset += 16
            if incl_len > len(data) - offset:
                break
            packet_count += 1
            captured_bytes += incl_len
            offset += incl_len
        return [
            "format=pcap",
            f"version={version_major}.{version_minor}",
            f"linktype={linktype}",
            f"snaplen={snaplen}",
            f"packet_count={packet_count}",
            f"captured_bytes={captured_bytes}",
        ]

    @staticmethod
    def _pcapng_summary_lines(data: bytes) -> list[str]:
        if len(data) < 12:
            return ["format=pcapng"]
        byte_order_magic = data[8:12]
        if byte_order_magic == b"\x4d\x3c\x2b\x1a":
            endian = "<"
        elif byte_order_magic == b"\x1a\x2b\x3c\x4d":
            endian = ">"
        else:
            endian = "<"
        interface_count = 0
        packet_count = 0
        captured_bytes = 0
        offset = 0
        while offset + 12 <= len(data) and packet_count < 1024:
            try:
                block_type, block_length = struct.unpack(f"{endian}II", data[offset : offset + 8])
            except struct.error:
                break
            if block_length < 12 or offset + block_length > len(data):
                break
            if block_type == 0x00000001:
                interface_count += 1
            elif block_type == 0x00000006 and block_length >= 32:
                try:
                    captured_length = struct.unpack(f"{endian}I", data[offset + 20 : offset + 24])[0]
                except struct.error:
                    captured_length = 0
                packet_count += 1
                captured_bytes += min(captured_length, max(0, block_length - 32))
            elif block_type == 0x00000003 and block_length >= 16:
                try:
                    captured_length = struct.unpack(f"{endian}I", data[offset + 8 : offset + 12])[0]
                except struct.error:
                    captured_length = 0
                packet_count += 1
                captured_bytes += min(captured_length, max(0, block_length - 16))
            offset += block_length
        return [
            "format=pcapng",
            f"interface_count={interface_count}",
            f"packet_count={packet_count}",
            f"captured_bytes={captured_bytes}",
        ]

    @staticmethod
    def _looks_like_warc_bytes(data: bytes, member_name: str = "") -> bool:
        lowered = str(member_name or "").strip().lower()
        if lowered.endswith(".warc") or ".warc#" in lowered:
            return True
        stripped = data[:64].lstrip()
        return stripped.startswith(b"WARC/")

    def _extract_warc_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_warc_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_warc_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._looks_like_warc_bytes(data, member_name):
            return self._member_payloads(source_file, member_name, data)
        payloads = self._warc_payload_tuples(
            data[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            member_name,
        )
        return payloads or self._member_payloads(source_file, member_name, data)

    def _warc_payload_tuples(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        job_batches = self._run_ordered_local_batch(
            list(enumerate(self._iter_warc_records(data)[:24], start=1)),
            lambda record_job: self._warc_record_job(
                record_job,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        record_jobs = [
            job
            for job in job_batches
            if isinstance(job, WARCRecordExtractionJob)
        ]
        ordered_payloads = self._run_ordered_local_batch(
            record_jobs,
            self._extract_warc_record_payloads,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (record_index, record_payloads or [])
                for record_index, record_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        for record_payloads in prepared_payloads:
            payloads.extend(record_payloads)
        return payloads

    @staticmethod
    def _warc_record_job(
        record_job: tuple[int, bytes],
        *,
        source_file: str,
        member_name: str,
    ) -> WARCRecordExtractionJob | None:
        record_index, record = record_job
        if record_index <= 0:
            return None
        return WARCRecordExtractionJob(
            source_file=source_file,
            member_name=member_name,
            record_index=record_index,
            record=record,
        )

    def _extract_warc_record_payloads(
        self,
        job: WARCRecordExtractionJob,
    ) -> list[tuple[str, str, str]]:
        summary_lines, body_text = self._warc_record_payload(job.record)
        payload_families = self._run_ordered_local_batch(
            ("summary", "body"),
            lambda family: self._extract_warc_record_payload_family(
                family,
                job=job,
                summary_lines=summary_lines,
                body_text=body_text,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_warc_record_payload_family(
        self,
        family: str,
        *,
        job: WARCRecordExtractionJob,
        summary_lines: Sequence[str],
        body_text: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_warc_record_summary_payloads(job, summary_lines)
        if family == "body":
            return self._extract_warc_record_body_payloads(job, body_text)
        return []

    def _extract_warc_record_summary_payloads(
        self,
        job: WARCRecordExtractionJob,
        summary_lines: Sequence[str],
    ) -> list[tuple[str, str, str]]:
        if not summary_lines:
            return []
        return [
            (
                job.source_file,
                f"{job.member_name}#warc-record-{job.record_index}",
                "\n".join(summary_lines[:320]),
            )
        ]

    def _extract_warc_record_body_payloads(
        self,
        job: WARCRecordExtractionJob,
        body_text: str,
    ) -> list[tuple[str, str, str]]:
        if not body_text:
            return []
        return [
            (
                job.source_file,
                f"{job.member_name}#warc-body-{job.record_index}",
                body_text,
            )
        ]

    def _iter_warc_records(self, data: bytes) -> list[bytes]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        records: list[bytes] = []
        offset = 0
        while offset < len(bounded):
            start = bounded.find(b"WARC/", offset)
            if start == -1:
                break
            warc_header_bytes, remainder, separator_length = self._split_bytes_header_block(
                bounded[start:]
            )
            if not warc_header_bytes:
                break
            header_text = warc_header_bytes.decode("latin-1", errors="ignore")
            content_length = 0
            match = re.search(r"(?im)^Content-Length:\s*(\d+)\s*$", header_text)
            if match:
                try:
                    content_length = int(match.group(1))
                except (TypeError, ValueError):
                    content_length = 0
            body_start = start + len(warc_header_bytes) + separator_length
            if content_length > 0 and body_start + content_length <= len(bounded):
                record_end = body_start + content_length
            else:
                next_start = bounded.find(b"\nWARC/", max(body_start, start + 5))
                if next_start == -1:
                    record_end = len(bounded)
                else:
                    record_end = next_start + 1
            record = bounded[start:record_end].strip(b"\r\n")
            if record:
                records.append(record)
            offset = max(record_end, body_start)
            while offset < len(bounded) and bounded[offset : offset + 1] in {b"\r", b"\n"}:
                offset += 1
        return records

    def _warc_record_payload(
        self,
        record: bytes,
    ) -> tuple[list[str], str]:
        warc_header_bytes, content_bytes, _separator_length = self._split_bytes_header_block(record)
        if not warc_header_bytes:
            return [], ""
        http_header_bytes = b""
        body_bytes = content_bytes
        if self._looks_like_http_message_bytes(content_bytes):
            http_header_bytes, http_body_bytes, _http_separator_length = self._split_bytes_header_block(
                content_bytes
            )
            body_bytes = http_body_bytes
        family_results = self._run_ordered_local_batch(
            ("warc_summary", "http_summary", "body"),
            lambda family: self._warc_record_payload_family(
                family,
                warc_header_bytes=warc_header_bytes,
                http_header_bytes=http_header_bytes,
                body_bytes=body_bytes,
            ),
            default_factory=lambda: ([], ""),
        )
        prepared_family_entries = self._run_ordered_local_batch(
            list(enumerate(family_results)),
            self._warc_record_payload_family_entry,
            default_factory=lambda: None,
        )
        summary_lines: list[str] = []
        body_text = ""
        for family_entry in prepared_family_entries:
            if not isinstance(family_entry, dict):
                continue
            summary_lines.extend(list(family_entry.get("summary_lines") or []))
            family_body_text = str(family_entry.get("body_text") or "")
            if family_body_text and not body_text:
                body_text = family_body_text
        return summary_lines, body_text

    def _warc_record_payload_family(
        self,
        family: str,
        *,
        warc_header_bytes: bytes,
        http_header_bytes: bytes,
        body_bytes: bytes,
    ) -> tuple[list[str], str]:
        if family == "warc_summary":
            return (self._structured_header_lines(warc_header_bytes, prefix="warc"), "")
        if family == "http_summary":
            if not http_header_bytes:
                return ([], "")
            return (self._structured_header_lines(http_header_bytes, prefix="http"), "")
        if family == "body":
            return ([], self._har_text_from_bytes(body_bytes, limit=4096))
        return ([], "")

    @staticmethod
    def _warc_record_payload_family_entry(
        family_entry: tuple[int, tuple[Sequence[str], str]],
    ) -> dict[str, Any] | None:
        _family_index, payload = family_entry
        if not isinstance(payload, tuple) or len(payload) != 2:
            return None
        summary_lines, body_text = payload
        return {
            "summary_lines": [str(line) for line in summary_lines if str(line or "").strip()],
            "body_text": str(body_text or "").strip(),
        }

    @staticmethod
    def _split_bytes_header_block(data: bytes) -> tuple[bytes, bytes, int]:
        for separator in (b"\r\n\r\n", b"\n\n"):
            index = data.find(separator)
            if index != -1:
                return data[:index], data[index + len(separator) :], len(separator)
        return data, b"", 0

    @staticmethod
    def _looks_like_http_message_bytes(data: bytes) -> bool:
        if not data:
            return False
        header_bytes, _remainder, _separator_length = ArtifactQueueProcessor._split_bytes_header_block(data)
        first_line = header_bytes.splitlines()[0].strip() if header_bytes.splitlines() else b""
        if not first_line:
            return False
        if first_line.startswith(b"HTTP/"):
            return True
        return bool(re.match(rb"^[A-Z]{3,12}\s+\S+\s+HTTP/\d(?:\.\d+)?$", first_line))

    def _structured_header_lines(self, header_bytes: bytes, *, prefix: str) -> list[str]:
        text = header_bytes.decode("latin-1", errors="ignore").replace("\x00", "").strip()
        if not text:
            return []
        raw_lines = [line.strip() for line in text.splitlines() if line.strip()]
        if not raw_lines:
            return []
        lines = [f"{prefix}.start_line={raw_lines[0]}"]
        line_candidates = self._run_ordered_local_batch(
            raw_lines[1:64],
            lambda line: self._structured_header_line(prefix=prefix, line=line),
            default_factory=str,
        )
        lines.extend(candidate for candidate in line_candidates if candidate)
        return lines

    @staticmethod
    def _structured_header_line(*, prefix: str, line: str) -> str:
        if ":" not in line:
            return f"{prefix}.line={line}"
        name, value = line.split(":", 1)
        normalized_name = re.sub(r"[^a-z0-9]+", "_", name.strip().lower()).strip("_")
        if prefix == "warc" and normalized_name.startswith("warc_"):
            normalized_name = normalized_name[len("warc_") :]
        if normalized_name:
            return f"{prefix}.{normalized_name}={value.strip()}"
        return f"{prefix}.line={line}"

    def _extract_har_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_HAR_BYTES]
        payloads = self._extract_har_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_har_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        text = self._har_text_from_bytes(data, limit=_MAX_HAR_BYTES)
        if not text.strip():
            return self._member_payloads(source_file, member_name, data)
        try:
            payload = json.loads(text)
        except Exception:  # noqa: BLE001
            return self._member_payloads(source_file, member_name, data)
        har_payloads = self._har_payload_tuples(payload, source_file, member_name)
        return har_payloads or self._member_payloads(source_file, member_name, data)

    def _har_payload_tuples(
        self,
        payload: Any,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not isinstance(payload, dict):
            return []
        log_payload = payload.get("log")
        if not isinstance(log_payload, dict):
            return []
        payload_families = self._run_ordered_local_batch(
            ("summary", "entries"),
            lambda family: self._extract_har_payload_family(
                family,
                log_payload=log_payload,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_har_payload_family(
        self,
        family: str,
        *,
        log_payload: dict[str, Any],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_har_summary_payloads(
                log_payload,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "entries":
            return self._extract_har_entry_payloads(
                log_payload,
                source_file=source_file,
                member_name=member_name,
            )
        return []

    def _extract_har_summary_payloads(
        self,
        log_payload: dict[str, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        line_families = self._run_ordered_local_batch(
            ("version", "creator", "browser", "pages", "entries"),
            lambda family: self._har_summary_family_lines(family, log_payload=log_payload),
            default_factory=list,
        )
        prepared_line_families = self._run_ordered_local_batch(
            list(enumerate(line_families)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        summary_lines: list[str] = []
        for family_lines in prepared_line_families:
            summary_lines.extend(family_lines)
        if not summary_lines:
            return []
        return [(source_file, f"{member_name}#har-summary", "\n".join(summary_lines[:96]))]

    def _har_summary_family_lines(
        self,
        family: str,
        *,
        log_payload: dict[str, Any],
    ) -> list[str]:
        if family == "version":
            return self._har_summary_version_lines(log_payload)
        if family == "creator":
            return self._har_summary_creator_lines(log_payload)
        if family == "browser":
            return self._har_summary_browser_lines(log_payload)
        if family == "pages":
            return self._har_summary_page_lines(log_payload)
        if family == "entries":
            return self._har_summary_entry_count_lines(log_payload)
        return []

    def _har_summary_version_lines(self, log_payload: dict[str, Any]) -> list[str]:
        version = str(log_payload.get("version") or "").strip()
        if version:
            return [f"log.version={version}"]
        return []

    def _har_summary_creator_lines(self, log_payload: dict[str, Any]) -> list[str]:
        creator = log_payload.get("creator")
        if not isinstance(creator, dict):
            return []
        creator_name = str(creator.get("name") or "").strip()
        creator_version = str(creator.get("version") or "").strip()
        if creator_name or creator_version:
            return [f"creator={creator_name or 'unknown'} {creator_version}".strip()]
        return []

    def _har_summary_browser_lines(self, log_payload: dict[str, Any]) -> list[str]:
        browser = log_payload.get("browser")
        if not isinstance(browser, dict):
            return []
        browser_name = str(browser.get("name") or "").strip()
        browser_version = str(browser.get("version") or "").strip()
        if browser_name or browser_version:
            return [f"browser={browser_name or 'unknown'} {browser_version}".strip()]
        return []

    def _har_summary_page_lines(self, log_payload: dict[str, Any]) -> list[str]:
        pages = log_payload.get("pages")
        if not isinstance(pages, list):
            return []
        lines = [f"pages={len(pages)}"]
        line_batches = self._run_ordered_local_batch(
            list(enumerate(pages[:8], start=1)),
            self._har_summary_page_line_batch,
            default_factory=list,
        )
        prepared_line_batches = self._run_ordered_local_batch(
            list(enumerate(line_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        for line_batch in prepared_line_batches:
            lines.extend(line_batch)
        return lines

    def _har_summary_page_line_batch(self, page_job: tuple[int, Any]) -> list[str]:
        index, page = page_job
        if not isinstance(page, dict):
            return []
        lines: list[str] = []
        title = self._har_scalar_text(page.get("title"))
        page_id = self._har_scalar_text(page.get("id"))
        started = self._har_scalar_text(page.get("startedDateTime"))
        if title:
            lines.append(f"page[{index}].title={title}")
        if page_id:
            lines.append(f"page[{index}].id={page_id}")
        if started:
            lines.append(f"page[{index}].started={started}")
        return lines

    def _har_summary_entry_count_lines(self, log_payload: dict[str, Any]) -> list[str]:
        entries = log_payload.get("entries")
        if isinstance(entries, list):
            return [f"entries={len(entries)}"]
        return []

    def _extract_har_entry_payloads(
        self,
        log_payload: dict[str, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        entries = log_payload.get("entries")
        if not isinstance(entries, list):
            return []
        entry_job_batches = self._run_ordered_local_batch(
            list(enumerate(entries[:24], start=1)),
            lambda item: self._har_entry_job(
                item,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        entry_jobs = [
            entry_job
            for entry_job in entry_job_batches
            if isinstance(entry_job, HAREntryExtractionJob)
        ]
        ordered_payloads = self._run_ordered_local_batch(
            entry_jobs,
            self._extract_har_entry_payload,
            default_factory=lambda: None,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (entry_index, [entry_payload] if entry_payload is not None else [])
                for entry_index, entry_payload in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for entry_payloads in prepared_payloads:
            payloads.extend(entry_payloads)
        return payloads

    @staticmethod
    def _har_entry_job(
        item: tuple[int, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> HAREntryExtractionJob | None:
        entry_index, entry = item
        return HAREntryExtractionJob(
            source_file=source_file,
            member_name=member_name,
            entry_index=int(entry_index),
            entry=entry,
        )

    def _extract_har_entry_payload(
        self,
        job: HAREntryExtractionJob,
    ) -> tuple[str, str, str] | None:
        entry_lines = self._har_entry_lines(job.entry)
        if not entry_lines:
            return None
        return (
            job.source_file,
            f"{job.member_name}#har-entry-{job.entry_index}",
            "\n".join(entry_lines[:320]),
        )

    def _har_entry_lines(self, entry: Any) -> list[str]:
        if not isinstance(entry, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("started", "request", "response", "websocket_messages"),
            lambda family: self._har_entry_family_lines(family, entry=entry),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_entry_family_lines(
        self,
        family: str,
        *,
        entry: dict[str, Any],
    ) -> list[str]:
        if family == "started":
            return self._har_entry_started_lines(entry)
        if family == "request":
            return self._har_request_lines(entry.get("request"))
        if family == "response":
            return self._har_response_lines(entry.get("response"))
        if family == "websocket_messages":
            return self._har_websocket_message_lines(entry)
        return []

    def _har_entry_started_lines(self, entry: dict[str, Any]) -> list[str]:
        started = self._har_scalar_text(entry.get("startedDateTime"))
        if started:
            return [f"startedDateTime={started}"]
        return []

    def _har_websocket_message_lines(self, entry: dict[str, Any]) -> list[str]:
        messages = self._har_websocket_message_values(entry)
        if not isinstance(messages, list):
            return []
        message_batches = self._run_ordered_local_batch(
            list(enumerate(messages[:64], start=1)),
            self._har_websocket_message_line_batch,
            default_factory=list,
        )
        lines: list[str] = []
        for message_lines in message_batches:
            lines.extend(message_lines)
        return lines

    def _har_websocket_message_line_batch(self, item: tuple[int, Any]) -> list[str]:
        message_index, message = item
        if not isinstance(message, dict):
            return []
        lines: list[str] = []
        for key, limit in (
            ("type", 64),
            ("time", 64),
            ("opcode", 64),
            ("data", 4096),
        ):
            value = self._har_scalar_text(message.get(key), limit=limit)
            if value:
                lines.append(f"websocket.message[{message_index}].{key}={value}")
        return lines

    @staticmethod
    def _har_websocket_message_values(entry: dict[str, Any]) -> Any:
        messages = entry.get("_webSocketMessages")
        if isinstance(messages, list):
            return messages
        return entry.get("webSocketMessages")

    def _har_request_lines(self, request: Any) -> list[str]:
        if not isinstance(request, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("request_line", "headers", "query", "cookies", "post_data"),
            lambda family: self._har_request_family_lines(family, request=request),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_request_family_lines(
        self,
        family: str,
        *,
        request: dict[str, Any],
    ) -> list[str]:
        if family == "request_line":
            return self._har_request_start_lines(request)
        if family == "headers":
            return self._har_request_header_lines(request)
        if family == "query":
            return self._har_request_query_lines(request)
        if family == "cookies":
            return self._har_request_cookie_lines(request)
        if family == "post_data":
            return self._har_request_post_data_lines(request)
        return []

    def _har_request_start_lines(self, request: dict[str, Any]) -> list[str]:
        lines: list[str] = []
        request_method = self._har_scalar_text(request.get("method"))
        request_url = self._har_scalar_text(request.get("url"), limit=2048)
        if request_method:
            lines.append(f"request.method={request_method}")
        if request_url:
            lines.append(f"request.url={request_url}")
        return lines

    def _har_request_header_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.header", request.get("headers"))

    def _har_request_query_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.query", request.get("queryString"))

    def _har_request_cookie_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.cookie", request.get("cookies"))

    def _har_request_post_data_lines(self, request: dict[str, Any]) -> list[str]:
        post_data = request.get("postData")
        if not isinstance(post_data, dict):
            return []
        lines: list[str] = []
        mime_type = self._har_scalar_text(post_data.get("mimeType"))
        if mime_type:
            lines.append(f"request.postData.mimeType={mime_type}")
        lines.extend(self._har_name_value_lines("request.postData.param", post_data.get("params")))
        post_text = self._har_scalar_text(post_data.get("text"), limit=4096)
        if post_text:
            lines.append(f"request.postData.text={post_text}")
        return lines

    def _har_response_lines(self, response: Any) -> list[str]:
        if not isinstance(response, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("status_line", "headers", "content"),
            lambda family: self._har_response_family_lines(family, response=response),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_response_family_lines(
        self,
        family: str,
        *,
        response: dict[str, Any],
    ) -> list[str]:
        if family == "status_line":
            return self._har_response_status_lines(response)
        if family == "headers":
            return self._har_response_header_lines(response)
        if family == "content":
            return self._har_response_content_lines(response)
        return []

    def _har_response_status_lines(self, response: dict[str, Any]) -> list[str]:
        lines: list[str] = []
        status_value = self._har_scalar_text(response.get("status"))
        redirect_url = self._har_scalar_text(response.get("redirectURL"), limit=2048)
        if status_value:
            lines.append(f"response.status={status_value}")
        if redirect_url:
            lines.append(f"response.redirectURL={redirect_url}")
        return lines

    def _har_response_header_lines(self, response: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("response.header", response.get("headers"))

    def _har_response_content_lines(self, response: dict[str, Any]) -> list[str]:
        response_content = response.get("content")
        if not isinstance(response_content, dict):
            return []
        lines: list[str] = []
        mime_type = self._har_scalar_text(response_content.get("mimeType"))
        if mime_type:
            lines.append(f"response.content.mimeType={mime_type}")
        image_payload_lines = self._har_content_image_payload_lines(response_content, mime_type=mime_type)
        if image_payload_lines:
            lines.extend(image_payload_lines)
            return lines
        content_text = self._har_content_text(response_content)
        if content_text:
            lines.append(f"response.content.text={content_text}")
        return lines

    def _har_content_text(self, content: dict[str, Any]) -> str:
        return har_content_text(
            content,
            scalar_text=lambda value, limit: self._har_scalar_text(value, limit=limit),
            text_from_bytes=lambda data, limit: self._har_text_from_bytes(data, limit=limit),
        )

    def _har_content_image_payload_lines(
        self,
        content: dict[str, Any],
        *,
        mime_type: str,
    ) -> list[str]:
        return har_content_image_payload_lines(
            content,
            mime_type=mime_type,
            suffix=_suffix_from_content_type(mime_type),
            image_suffixes=_OCR_IMAGE_SUFFIXES,
            max_image_bytes=_MAX_OCR_IMAGE_BYTES,
            ocr_text_limit=_OCR_TEXT_LIMIT,
            ocr_image_bytes=self._ocr_image_bytes,
            image_metadata_payload=self._image_metadata_payload,
        )

    def _har_name_value_lines(
        self,
        prefix: str,
        values: Any,
    ) -> list[str]:
        if not isinstance(values, list):
            return []
        line_candidates = self._run_ordered_local_batch(
            values[:32],
            lambda item: self._har_name_value_line(prefix, item),
            default_factory=str,
        )
        return [line for line in line_candidates if line]

    def _har_name_value_line(
        self,
        prefix: str,
        item: Any,
    ) -> str:
        if not isinstance(item, dict):
            return ""
        name = self._har_scalar_text(item.get("name"))
        value = self._har_scalar_text(
            item.get("value") if "value" in item else item.get("comment"),
            limit=2048,
        )
        if not value:
            return ""
        if name:
            return f"{prefix}.{name}={value}"
        return f"{prefix}={value}"

    @staticmethod
    def _har_scalar_text(value: Any, *, limit: int = 512) -> str:
        return har_scalar_text(value, limit=limit)

    @classmethod
    def _har_text_from_bytes(cls, data: bytes, *, limit: int = _MAX_ARTIFACT_MEMBER_BYTES) -> str:
        bounded = data[:limit]
        decode_entries = [(encoding, bounded) for encoding in ("utf-8-sig", "utf-8", "latin-1")]
        decoded_candidates = cls._run_ordered_static_batch(
            decode_entries,
            cls._har_text_decode_entry,
            default_factory=str,
            max_workers=len(decode_entries),
        )
        for text in decoded_candidates:
            if not text:
                continue
            if any(char.isalpha() for char in text[:512]) or "://" in text or "@" in text:
                return text
        return ""

    @staticmethod
    def _har_text_decode_entry(entry: tuple[str, bytes]) -> str:
        encoding, bounded = entry
        try:
            return bounded.decode(encoding, errors="ignore").replace("\x00", "").strip()
        except Exception:  # noqa: BLE001
            return ""

    def _extract_plist_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_plist_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_embedded_plist_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_embedded_plist_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_plist_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        try:
            payload = plistlib.loads(data)
        except Exception:  # noqa: BLE001
            return self._member_payloads(source_file, member_name, data)

        payloads: list[tuple[str, str, str]] = []
        payload_fragments = self._run_ordered_local_batch(
            ("xml", "values"),
            lambda family: self._extract_plist_payload_fragment(
                family,
                payload=payload,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        for fragment in payload_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_plist_payload_fragment(
        self,
        family: str,
        *,
        payload: Any,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "xml":
            try:
                xml_text = plistlib.dumps(payload, fmt=plistlib.FMT_XML, sort_keys=True).decode(
                    "utf-8",
                    errors="ignore",
                )
            except Exception:  # noqa: BLE001
                xml_text = ""
            if xml_text.strip():
                return [(source_file, f"{member_name}#plist-xml", self._xml_text_payload(xml_text))]
            return []
        if family == "values":
            flattened_lines = self._plist_text_lines(payload)
            if flattened_lines:
                return [(source_file, f"{member_name}#plist-values", "\n".join(flattened_lines[:256]))]
            return []
        return []

    def _extract_embedded_plist_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        plist_bytes = self._embedded_plist_bytes(data)
        if plist_bytes is None:
            return self._member_payloads(source_file, member_name, data)
        return self._extract_plist_bytes_payloads(
            plist_bytes[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            f"{member_name}#embedded-plist",
        )

    @staticmethod
    def _embedded_plist_bytes(data: bytes) -> bytes | None:
        if not data:
            return None
        stripped = data.lstrip()
        if stripped.startswith(_PLIST_MAGIC) or stripped.startswith(b"<?xml") or stripped.startswith(b"<plist"):
            return stripped

        xml_start = data.find(b"<?xml")
        if xml_start == -1:
            xml_start = data.find(b"<plist")
        if xml_start != -1:
            xml_end = data.find(b"</plist>", xml_start)
            if xml_end != -1:
                return data[xml_start : xml_end + len(b"</plist>")]

        binary_start = data.find(_PLIST_MAGIC)
        if binary_start != -1:
            return data[binary_start:]
        return None

    def _plist_text_lines(
        self,
        value: Any,
        prefix: str = "",
    ) -> list[str]:
        if not isinstance(value, (dict, list, tuple)):
            rendered = self._plist_scalar_text(value)
            if not rendered:
                return []
            label = prefix or "value"
            return [f"{label}={rendered}"]

        entry_jobs = self._run_ordered_local_batch(
            self._plist_entry_job_sources(value),
            lambda entry_job: self._plist_entry_job(
                entry_job,
                prefix=prefix,
            ),
            default_factory=lambda: None,
        )
        entry_jobs = [
            entry_job
            for entry_job in entry_jobs
            if isinstance(entry_job, tuple)
        ]
        entry_batches = self._run_ordered_local_batch(
            entry_jobs,
            self._plist_entry_lines,
            default_factory=list,
        )
        prepared_entry_batches = self._run_ordered_local_batch(
            list(enumerate(entry_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        lines: list[str] = []
        for batch in prepared_entry_batches:
            lines.extend(batch)
        return lines

    def _plist_entry_lines(self, entry_job: tuple[str, Any]) -> list[str]:
        nested_prefix, item = entry_job
        return self._plist_text_lines(item, nested_prefix)

    @staticmethod
    def _plist_entry_job_sources(
        value: Any,
    ) -> list[tuple[Any, Any]]:
        if isinstance(value, dict):
            return list(value.items())
        if isinstance(value, (list, tuple)):
            return list(enumerate(value))
        return []

    @staticmethod
    def _plist_entry_job(
        entry_source: tuple[Any, Any],
        *,
        prefix: str,
    ) -> tuple[str, Any] | None:
        key_or_index, item = entry_source
        if isinstance(key_or_index, int):
            nested_prefix = f"{prefix}[{key_or_index}]" if prefix else f"[{key_or_index}]"
            return nested_prefix, item
        key_text = str(key_or_index or "").strip() or "key"
        nested_prefix = f"{prefix}.{key_text}" if prefix else key_text
        return nested_prefix, item

    @staticmethod
    def _plist_scalar_text(value: Any) -> str:
        def _bounded(text: str, limit: int = 512) -> str:
            cleaned = str(text or "").strip()
            if len(cleaned) <= limit:
                return cleaned
            return f"{cleaned[: limit - 3]}..."

        if value is None:
            return ""
        if isinstance(value, bytes):
            text = value[:_MAX_ARTIFACT_MEMBER_BYTES].decode("utf-8", errors="ignore").strip()
            if not text:
                text = value[:_MAX_ARTIFACT_MEMBER_BYTES].decode("latin-1", errors="ignore").strip()
            return _bounded(text)
        if isinstance(value, (str, int, float, bool)):
            return _bounded(str(value))
        if isinstance(value, datetime):
            return value.isoformat()
        return _bounded(str(value))

    @staticmethod
    def _sqlite_identifier(name: str) -> str:
        escaped = str(name or "").replace('"', '""')
        return f'"{escaped}"'

    @staticmethod
    def _sqlite_cell_text(value: Any) -> str:
        def _bounded(text: str, limit: int) -> str:
            cleaned = str(text or "").strip()
            if len(cleaned) <= limit:
                return cleaned
            return f"{cleaned[: limit - 3]}..."

        if value is None:
            return ""
        if isinstance(value, bytes):
            text = value[:_MAX_SQLITE_TEXT_BYTES].decode("utf-8", errors="ignore").strip()
            if not text:
                text = value[:_MAX_SQLITE_TEXT_BYTES].decode("latin-1", errors="ignore").strip()
            return _bounded(text, 512)
        if isinstance(value, str):
            return _bounded(value, 512)
        if isinstance(value, (int, float)):
            return _bounded(str(value), 128)
        return _bounded(str(value), 256)

    def _extract_sqlite_connection_payloads(
        self,
        con: sqlite3.Connection,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        try:
            object_rows = con.execute(
                """
                SELECT type, name, sql
                FROM sqlite_master
                WHERE type IN ('table', 'view')
                  AND name NOT LIKE 'sqlite_%'
                ORDER BY name ASC
                LIMIT ?
                """,
                (_MAX_SQLITE_TABLES,),
            ).fetchall()
        except sqlite3.Error:
            return payloads

        job_batches = self._run_ordered_local_batch(
            object_rows,
            lambda object_row: self._sqlite_object_job(
                object_row,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        jobs = [
            job
            for job in job_batches
            if isinstance(job, SQLiteObjectExtractionJob)
        ]
        if not jobs:
            return payloads

        database_path = self._sqlite_connection_path(con)
        if database_path:
            for job in jobs:
                job.database_path = database_path

        if len(jobs) == 1 or self._max_workers <= 1 or not database_path:
            payloads.extend(
                self._extract_sqlite_connection_summary_payloads(
                    jobs,
                    source_file=source_file,
                    member_name=member_name,
                )
            )
            for job in jobs:
                payloads.extend(
                    self._extract_sqlite_object_payloads_from_connection(
                        con,
                        source_file=job.source_file,
                        member_name=job.member_name,
                        object_name=job.object_name,
                        object_sql=job.object_sql,
                    )
                )
            return payloads

        payloads.extend(
            _orchestration_extract_sqlite_connection_payloads_from_jobs(
                jobs,
                source_file=source_file,
                member_name=member_name,
                run_ordered_batch=self._run_ordered_local_batch,
                extract_sqlite_connection_payload_family=(
                    lambda family, jobs, source_file, member_name: (
                        self._extract_sqlite_connection_payload_family(
                            family,
                            jobs=list(jobs),
                            source_file=source_file,
                            member_name=member_name,
                        )
                    )
                ),
                artifact_payload_tuple_batch_entries=self._artifact_payload_tuple_batch_entries,
            )
        )
        return payloads

    @staticmethod
    def _sqlite_object_job(
        object_row: Sequence[Any],
        *,
        source_file: str,
        member_name: str,
    ) -> SQLiteObjectExtractionJob | None:
        _object_type, object_name, object_sql = object_row
        name = str(object_name or "").strip()
        if not name:
            return None
        return SQLiteObjectExtractionJob(
            database_path="",
            source_file=source_file,
            member_name=member_name,
            object_name=name,
            object_sql=str(object_sql or "").strip(),
        )

    def _extract_sqlite_connection_payload_family(
        self,
        family: str,
        *,
        jobs: list[SQLiteObjectExtractionJob],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        return _orchestration_extract_sqlite_connection_payload_family(
            family,
            jobs=jobs,
            source_file=source_file,
            member_name=member_name,
            extract_sqlite_connection_summary_payloads=(
                lambda jobs, source_file, member_name: (
                    self._extract_sqlite_connection_summary_payloads(
                        list(jobs),
                        source_file=source_file,
                        member_name=member_name,
                    )
                )
            ),
            extract_sqlite_connection_object_payloads=(
                lambda jobs: self._extract_sqlite_connection_object_payloads(list(jobs))
            ),
        )

    def _extract_sqlite_connection_summary_payloads(
        self,
        jobs: list[SQLiteObjectExtractionJob],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        object_names = [job.object_name for job in jobs if str(job.object_name or "").strip()]
        if not object_names:
            return []
        return [
            (
                source_file,
                f"{member_name}#sqlite-meta",
                "objects=" + ", ".join(object_names[:_MAX_SQLITE_TABLES]),
            )
        ]

    def _extract_sqlite_connection_object_payloads(
        self,
        jobs: list[SQLiteObjectExtractionJob],
    ) -> list[tuple[str, str, str]]:
        return _orchestration_extract_sqlite_connection_object_payloads_from_jobs(
            jobs,
            run_ordered_batch=self._run_ordered_local_batch,
            extract_sqlite_object_payloads=self._extract_sqlite_object_payloads,
            artifact_payload_tuple_batch_entries=self._artifact_payload_tuple_batch_entries,
        )

    @staticmethod
    def _sqlite_connection_path(con: sqlite3.Connection) -> str:
        try:
            rows = con.execute("PRAGMA database_list").fetchall()
        except sqlite3.Error:
            return ""
        for row in rows:
            try:
                database_name = str(row[1] or "").strip().lower()
                database_path = str(row[2] or "").strip()
            except Exception:  # noqa: BLE001
                continue
            if database_name == "main" and database_path:
                return database_path
        return ""

    def _extract_sqlite_object_payloads(
        self,
        job: SQLiteObjectExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if not job.database_path:
            return []
        database_uri = f"file:{Path(job.database_path).as_posix()}?mode=ro"
        try:
            con = direct_connect(database_uri, uri=True)
        except sqlite3.Error:
            return []
        try:
            return self._extract_sqlite_object_payloads_from_connection(
                con,
                source_file=job.source_file,
                member_name=job.member_name,
                object_name=job.object_name,
                object_sql=job.object_sql,
            )
        finally:
            con.close()

    def _extract_sqlite_object_payloads_from_connection(
        self,
        con: sqlite3.Connection,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        object_sql: str,
    ) -> list[tuple[str, str, str]]:
        return _orchestration_extract_sqlite_object_payloads_from_connection(
            con,
            source_file=source_file,
            member_name=member_name,
            object_name=object_name,
            object_sql=object_sql,
            max_sqlite_rows_per_table=_MAX_SQLITE_ROWS_PER_TABLE,
            sqlite_identifier=self._sqlite_identifier,
            run_ordered_batch=self._run_ordered_local_batch,
            extract_sqlite_object_payload_family=self._extract_sqlite_object_payload_family,
            artifact_payload_tuple_batch_entries=self._artifact_payload_tuple_batch_entries,
        )

    @staticmethod
    def _artifact_payload_tuple_batch_entries(
        payload_batch: tuple[int, Sequence[tuple[str, str, str]]],
    ) -> list[tuple[str, str, str]]:
        _batch_index, batch = payload_batch
        payloads: list[tuple[str, str, str]] = []
        for payload in batch:
            if not isinstance(payload, tuple) or len(payload) != 3:
                continue
            source_file, member_name, text = payload
            source_file_text = str(source_file or "").strip()
            member_name_text = str(member_name or "").strip()
            text_value = str(text or "")
            if source_file_text and member_name_text and text_value:
                payloads.append((source_file_text, member_name_text, text_value))
        return payloads

